// Data grammar-n5 — dihasilkan otomatis (lihat scripts/fetch-data.mjs).
export default [{"pattern":"A が いちばん～","meaning":"Express the superlative degree; 'the most', 'the best', 'the least'.","formation":"Noun + が + いちばん + Adjective/Verb","examples":[{"jp":"この中で、寿司が一番好きです。","en":"Of all these, I like sushi the most.","romaji":"Kono naka de, sushi ga ichiban suki desu."},{"jp":"彼女はクラスで一番速く泳げます。","en":"She can swim the fastest in the class.","romaji":"Kanojo wa kurasu de ichiban hayaku oyogemasu."},{"jp":"この町では、この公園が一番きれいです。","en":"In this town, this park is the most beautiful.","romaji":"Kono machi de wa, kono kouen ga ichiban kirei desu."},{"jp":"飲み物の中では、紅茶が一番好きです。","en":"Among all drinks, I like tea the most.","romaji":"Nomimono no naka de wa, koucha ga ichiban suki desu."}],"example":"この中で、寿司が一番好きです。","exampleMeaning":"Of all these, I like sushi the most."},{"pattern":"A。けれども、～B。(A. Keredomo,~ B.)","meaning":"Used to express a contrast between two statements. It can be translated as 'but' or 'however'.","formation":"Statement A + けれども、+ Statement B","examples":[{"jp":"今日は晴れている。けれども、寒いです。","en":"It is sunny today. However, it is cold.","romaji":"Kyou wa harete iru. Keredo mo, samui desu."},{"jp":"彼女はうるさい。けれども、面白いです。","en":"She is noisy. But, she is interesting.","romaji":"Kanojo wa urusai. Keredo mo, omoshiroi desu."},{"jp":"その映画は長かった。けれども、退屈じゃなかった。","en":"The movie was long. But, it wasn't boring.","romaji":"Sono eiga wa nagakatta. Keredo mo, taikutsu janakatta."},{"jp":"彼は運動が得意だ。けれども、勉強は苦手だ。","en":"He is good at sports. However, he is not good at studying.","romaji":"Kare wa undou ga tokui da. Keredo mo, benkyou wa nigate da."}],"example":"今日は晴れている。けれども、寒いです。","exampleMeaning":"It is sunny today. However, it is cold."},{"pattern":"A。しかし、～B。 (A. Shikashi, ~B.)","meaning":"Expresses contrast or contradiction between two clauses; 'A, but B', 'A, however B'.","formation":"Sentence A + しかし + Sentence B.","examples":[{"jp":"今日は忙しい。しかし、時間があるなら、コーヒーを飲もう。","en":"I'm busy today. However, if I have time, let's have coffee.","romaji":"Kyou wa isogashii. Shikashi, jikan ga aru nara, koohii o nomou."},{"jp":"その映画は面白かった。しかし、長すぎました。","en":"The movie was interesting. But, it was too long.","romaji":"Sono eiga wa omoshirokatta. Shikashi, nagasugimashita."},{"jp":"彼は疲れていた。しかし、宿題を終わらせた。","en":"He was tired. However, he finished his homework.","romaji":"Kare wa tsukareteita. Shikashi, shukudai o owaraseta."},{"jp":"部屋は狭いです。しかし、便利な場所にあります。","en":"The room is small. But, it is in a convenient location.","romaji":"Heya wa semai desu. Shikashi, benri na basho ni arimasu."}],"example":"今日は忙しい。しかし、時間があるなら、コーヒーを飲もう。","exampleMeaning":"I'm busy today. However, if I have time, let's have coffee."},{"pattern":"A。じゃ、～B。(A. Ja, ~B.)","meaning":"Indicates a decision or suggestion; 'well then', 'in that case', 'so'.","formation":"A: Sentence, B: Sentence (A and B can be any sentence type)","examples":[{"jp":"映画は時間がない。じゃ、また今度行こう。","en":"There's no time for a movie. Well then, let's go another time.","romaji":"Eiga wa jikan ga nai. Ja, mata kondo ikou."},{"jp":"お腹がすいた。じゃ、レストランに行こう。","en":"I'm hungry. In that case, let's go to a restaurant.","romaji":"Onaka ga suita. Ja, resutoran ni ikou."},{"jp":"電車が遅れた。じゃ、バスで行こう。","en":"The train is late. So, let's go by bus.","romaji":"Densha ga okureta. Ja, basu de ikou."},{"jp":"このシャツは高い。じゃ、別のを買おう。","en":"This shirt is expensive. Well then, let's buy a different one.","romaji":"Kono shatsu wa takai. Ja, betsu no o kau."}],"example":"映画は時間がない。じゃ、また今度行こう。","exampleMeaning":"There's no time for a movie. Well then, let's go another time."},{"pattern":"A。それじゃ、～B。(A. Soreja,~B.)","meaning":"Connect two sentences; 'A, so/in that case, B'","formation":"Sentence A + 。それじゃ、 + Sentence B","examples":[{"jp":"今日は休みです。それじゃ、映画を観に行きましょう。","en":"Today is a day off. In that case, let's go watch a movie.","romaji":"Kyou wa yasumi desu. Soreja, eiga wo mi ni ikimashou."},{"jp":"電気が切れた。それじゃ、ろうそくを使いましょう。","en":"The electricity went out. In that case, let's use candles.","romaji":"Denki ga kireta. Soreja, rousoku wo tsukaimashou."},{"jp":"レストランが混んでいます。それじゃ、別の場所で食べましょう。","en":"The restaurant is crowded. In that case, let's eat somewhere else.","romaji":"Resutoran ga kondeimasu. Soreja, betsu no basho de tabemashou."},{"jp":"明日は雨が降るらしい。それじゃ、ピクニックは中止しましょう。","en":"It seems it will rain tomorrow. In that case, let's cancel the picnic.","romaji":"Ashita wa ame ga furu rashii. Soreja, pikunikku wa chuushi shimashou."}],"example":"今日は休みです。それじゃ、映画を観に行きましょう。","exampleMeaning":"Today is a day off. In that case, let's go watch a movie."},{"pattern":"A。それでは、～B。(A. Soredewa,~B.)","meaning":"Express a change in situation; 'then', 'in that case', 'so'.","formation":"A (Statement) + 。それでは、 + B (Follow-up action or statement)","examples":[{"jp":"今日は休みだ。それでは、映画を見に行こう。","en":"Today is a day off. In that case, let's go see a movie.","romaji":"Kyou wa yasumi da. Sore dewa, eiga wo mi ni ikou."},{"jp":"このパンはもう古いです。それでは、捨てましょう。","en":"This bread is already old. Then, let's throw it away.","romaji":"Kono pan wa mou furui desu. Sore dewa, sutemashou."},{"jp":"雨が降ってきた。それでは、室内で遊ぼう。","en":"It started raining. In that case, let's play indoors.","romaji":"Ame ga futtekita. Sore dewa, shitsunai de asobou."},{"jp":"お腹が空いた。それでは、何か食べに行きましょう。","en":"I'm hungry. So, let's go eat something.","romaji":"Onaka ga suita. Sore dewa, nani ka tabe ni ikimashou."}],"example":"今日は休みだ。それでは、映画を見に行こう。","exampleMeaning":"Today is a day off. In that case, let's go see a movie."},{"pattern":"A。 では、～B。 (A. Dewa, ~B)","meaning":"Indicates a contrast or comparison between A and B; 'As for A, ~B'.","formation":"Noun A + では、 + Subject + Predicate B","examples":[{"jp":"果物では、リンゴが一番好きです。","en":"As for fruits, apples are my favorite.","romaji":"Kudamono dewa, ringo ga ichiban suki desu."},{"jp":"スポーツでは、サッカーが一番人気です。","en":"As for sports, soccer is the most popular.","romaji":"Supōtsu dewa, sakkā ga ichiban ninki desu."},{"jp":"今日の天気では、雨が降りそうです。","en":"As for today's weather, it looks like it will rain.","romaji":"Kyou no tenki dewa, ame ga furisou desu."},{"jp":"料理では、和食が一番得意です。","en":"As for cooking, I am best at Japanese cuisine.","romaji":"Ryouri dewa, washoku ga ichiban tokui desu."}],"example":"果物では、リンゴが一番好きです。","exampleMeaning":"As for fruits, apples are my favorite."},{"pattern":"A。でも、～B。(A. Demo, ~B)","meaning":"Used to express contrast between two statements; 'A, but B', 'A, however B'.","formation":"Clause A + でも + Clause B","examples":[{"jp":"昨日は寒かった。でも、今日は暖かいです。","en":"Yesterday was cold. But today it's warm.","romaji":"Kinou wa samukatta. Demo, kyou wa atatakai desu."},{"jp":"彼は忙しい。でも、友達と遊ぶ時間がある。","en":"He is busy. However, he still has time to hang out with friends.","romaji":"Kare wa isogashii. Demo, tomodachi to asobu jikan ga aru."},{"jp":"試験に合格した。でも、まだ勉強を続けています。","en":"I passed the exam. But I'm still continuing to study.","romaji":"Shiken ni goukaku shita. Demo, mada benkyou wo tsuzuketeimasu."},{"jp":"彼女は有名だ。でも、とても謙虚です。","en":"She is famous. However, she's very humble.","romaji":"Kanojo wa yuumei da. Demo, totemo kenkyo desu."}],"example":"昨日は寒かった。でも、今日は暖かいです。","exampleMeaning":"Yesterday was cold. But today it's warm."},{"pattern":"Aと Bと どちら～","meaning":"Used to ask which of two alternatives is preferred or to compare two things","formation":"Aと Bと どちら + Verb/Adjective/Noun","examples":[{"jp":"りんごとみかんとどちらが好きですか。","en":"Which do you like, apples or oranges?","romaji":"Ringo to mikan to dochira ga suki desu ka?"},{"jp":"電車とバスとどちらで行くべきですか。","en":"Should I go by train or bus?","romaji":"Densha to basu to dochira de iku beki desu ka?"},{"jp":"赤いワンピースと青いワンピースとどちらが似合うと思いますか。","en":"Which do you think suits me better, the red dress or the blue dress?","romaji":"Akai wanpiisu to aoi wanpiisu to dochira ga niau to omoimasu ka?"},{"jp":"このカメラとあのカメラとどちらのほうが使いやすいですか。","en":"Which one is easier to use, this camera or that camera?","romaji":"Kono kamera to ano kamera to dochira no hou ga tsukaiyasui desu ka?"}],"example":"りんごとみかんとどちらが好きですか。","exampleMeaning":"Which do you like, apples or oranges?"},{"pattern":"AとBと どっち〜 (A to B to docchi〜)","meaning":"Asking which one; 'which', 'A or B'.","formation":"AとBと どっち + Verb, AかBか どっち + Verb","examples":[{"jp":"コーヒーと紅茶とどっちが好き？","en":"Which do you like, coffee or tea?","romaji":"Koohii to koucha to docchi ga suki?"},{"jp":"映画と音楽とどっちを楽しむ？","en":"Which do you enjoy, movies or music?","romaji":"Eiga to ongaku to docchi o tanoshimu?"},{"jp":"赤いシャツと青いシャツとどっちを買う？","en":"Which one will you buy, the red shirt or the blue shirt?","romaji":"Akai shatsu to aoi shatsu to docchi o kau?"},{"jp":"日本語と韓国語とどっちを勉強したい？","en":"Which do you want to study, Japanese or Korean?","romaji":"Nihongo to kankokugo to docchi o benkyou shitai?"}],"example":"コーヒーと紅茶とどっちが好き？","exampleMeaning":"Which do you like, coffee or tea?"},{"pattern":"A は B が〜 (A wa B ga〜)","meaning":"Indicates that there is something unique or different about A and describes what is special about it.","formation":"A は (Topic) + B が (Characteristic/Feature) + Description/Action","examples":[{"jp":"彼女は髪が長いです。","en":"What's special about her is that she has long hair.","romaji":"Kanojo wa kami ga nagai desu."},{"jp":"このレストランは雰囲気が良いです。","en":"What's great about this restaurant is the atmosphere.","romaji":"Kono resutoran wa fun'iki ga ii desu."},{"jp":"私は朝ごはんが一番好きです。","en":"What I like the most is breakfast.","romaji":"Watashi wa asagohan ga ichiban suki desu."},{"jp":"彼は英語が得意です。","en":"He is particularly good at English.","romaji":"Kare wa eigo ga tokui desu."}],"example":"彼女は髪が長いです。","exampleMeaning":"What's special about her is that she has long hair."},{"pattern":"A は B より～","meaning":"Express a comparison between A and B; 'A is more/less than B'.","formation":"A は B より + Adjective","examples":[{"jp":"このジュースはあのジュースより甘いです。","en":"This juice is sweeter than that juice.","romaji":"Kono juusu wa ano juusu yori amai desu."},{"jp":"夏は冬より暑いです。","en":"Summer is hotter than winter.","romaji":"Natsu wa fuyu yori atsui desu."},{"jp":"彼女は私より速く走ります。","en":"She runs faster than me.","romaji":"Kanojo wa watashi yori hayaku hashirimasu."},{"jp":"スーパーはコンビニより安いです。","en":"The supermarket is cheaper than the convenience store.","romaji":"Suupaa wa konbini yori yasui desu."}],"example":"このジュースはあのジュースより甘いです。","exampleMeaning":"This juice is sweeter than that juice."},{"pattern":"A より B のほうが～","meaning":"Used to compare two items; 'B is more ～ than A'.","formation":"A + より + B + のほうが + Adjective","examples":[{"jp":"ピザよりハンバーガーのほうが美味しい。","en":"Hamburgers are more delicious than pizza.","romaji":"Piza yori hanbaagaa no hou ga oishii."},{"jp":"夏より冬のほうが寒い。","en":"Winter is colder than summer.","romaji":"Natsu yori fuyu no hou ga samui."},{"jp":"ここよりそこのほうが静かです。","en":"There is quieter than here.","romaji":"Koko yori soko no hou ga shizuka desu."},{"jp":"車より電車のほうが速い。","en":"Trains are faster than cars.","romaji":"Kuruma yori densha no hou ga hayai."}],"example":"ピザよりハンバーガーのほうが美味しい。","exampleMeaning":"Hamburgers are more delicious than pizza."},{"pattern":"い-Adjective く + Verb (i-Adjective + ku + Verb)","meaning":"Used to connect an い-adjective to a verb, modifying the verb (adverbial usage).","formation":"い-Adjective (remove い) + く + Verb","examples":[{"jp":"彼は速く走りました。","en":"He ran quickly.","romaji":"Kare wa hayaku hashirimashita."},{"jp":"この料理は美味しく食べました。","en":"I enjoyed eating this dish.","romaji":"Kono ryouri wa oishiku tabemashita."},{"jp":"彼女は優しく話します。","en":"She speaks kindly.","romaji":"Kanojo wa yasashiku hanashimasu."},{"jp":"母は忙しく仕事をしています。","en":"My mother is working busily.","romaji":"Haha wa isogashiku shigoto o shite imasu."}],"example":"彼は速く走りました。","exampleMeaning":"He ran quickly."},{"pattern":"い-Adjective く します (i-Adjective ku shimasu)","meaning":"Use an い-adjective to express 'to make' or 'to become'.","formation":"い-Adjective (remove い) + くします","examples":[{"jp":"部屋を明るくします。","en":"I will make the room brighter.","romaji":"Heya o akaruku shimasu."},{"jp":"友達の気分を楽しくします。","en":"I will make my friend’s mood more pleasant.","romaji":"Tomodachi no kibun o tanoshiku shimasu."},{"jp":"仕事が簡単になるように、やり方を早くします。","en":"I will make the way of doing things faster so that the work becomes easier.","romaji":"Shigoto ga kantan ni naru you ni, yarikata o hayaku shimasu."},{"jp":"食べ物を美味しくします。","en":"I will make the food delicious.","romaji":"Tabemono o oishiku shimasu."}],"example":"部屋を明るくします。","exampleMeaning":"I will make the room brighter."},{"pattern":"い-Adjective: Negative Polite Form","meaning":"Change an い-adjective into a polite negative form with ～くないです (or ～くありません).","formation":"い-Adjective (remove い) + くないです","examples":[{"jp":"このピザは美味しくないです。","en":"This pizza is not delicious.","romaji":"Kono piza wa oishiku nai desu."},{"jp":"この部屋は広くないです。","en":"This room is not spacious.","romaji":"Kono heya wa hiroku nai desu."},{"jp":"彼の意見は面白くないです。","en":"His opinion is not interesting.","romaji":"Kare no iken wa omoshiroku nai desu."},{"jp":"その映画は楽しくありません。","en":"That movie is not enjoyable.","romaji":"Sono eiga wa tanoshiku arimasen."}],"example":"このピザは美味しくないです。","exampleMeaning":"This pizza is not delicious."},{"pattern":"い-Adjective て (i-Adjective + te~)","meaning":"Used to connect two or more い-adjectives to describe something.","formation":"い-Adjective (remove い) + くて + い-Adjective","examples":[{"jp":"このリンゴは甘くて美味しいです。","en":"This apple is sweet and delicious.","romaji":"Kono ringo wa amakute oishii desu."},{"jp":"彼女は優しくてかわいいです。","en":"She is kind and cute.","romaji":"Kanojo wa yasashikute kawaii desu."},{"jp":"映画は面白くて感動的でした。","en":"The movie was interesting and moving.","romaji":"Eiga wa omoshirokute kandouteki deshita."},{"jp":"この部屋は広くて明るいです。","en":"This room is spacious and bright.","romaji":"Kono heya wa hirokute akarui desu."}],"example":"このリンゴは甘くて美味しいです。","exampleMeaning":"This apple is sweet and delicious."},{"pattern":"な-Adjective に + Verb","meaning":"Turn a な-adjective into an adverb by adding に.","formation":"な-Adjective (remove な) + に + Verb","examples":[{"jp":"彼は静かに話す。","en":"He speaks quietly.","romaji":"Kare wa shizuka ni hanasu."},{"jp":"部屋をきれいに掃除した。","en":"I cleaned the room neatly.","romaji":"Heya o kirei ni souji shita."},{"jp":"彼女は元気に働いています。","en":"She works energetically.","romaji":"Kanojo wa genki ni hataraite imasu."},{"jp":"先生は親切に説明してくれる。","en":"The teacher explains kindly.","romaji":"Sensei wa shinsetsu ni setsumei shite kureru."}],"example":"彼は静かに話す。","exampleMeaning":"He speaks quietly."},{"pattern":"な-Adjective で～ (na-Adjective de~)","meaning":"Usage of で to connect or add information with a な-adjective.","formation":"な-Adjective + で","examples":[{"jp":"彼は綺麗で優しい女性が好きです。","en":"He likes women who are beautiful and kind.","romaji":"Kare wa kirei de yasashii josei ga suki desu."},{"jp":"この料理は健康的で、元気な気分になります。","en":"This dish is healthy and makes you feel energetic.","romaji":"Kono ryouri wa kenkouteki de, genki na kibun ni narimasu."},{"jp":"彼は静かで落ち着いた環境で仕事をしたい。","en":"He wants to work in a quiet and calm environment.","romaji":"Kare wa shizuka de ochitsuita kankyou de shigoto o shitai."},{"jp":"この部屋は清潔で気持ちがいいです。","en":"This room is clean and feels good.","romaji":"Kono heya wa seiketsu de kimochi ga ii desu."}],"example":"彼は綺麗で優しい女性が好きです。","exampleMeaning":"He likes women who are beautiful and kind."},{"pattern":"な-Adjective に します (na-Adjective ni shimasu)","meaning":"Expressing a decision or preference with a な-adjective.","formation":"な-Adjective + に + します","examples":[{"jp":"静かにします。","en":"I will be quiet.","romaji":"Shizuka ni shimasu."},{"jp":"部屋をきれいにします。","en":"I will make the room clean.","romaji":"Heya o kirei ni shimasu."},{"jp":"明日の会議は簡単にします。","en":"I will make tomorrow’s meeting simple.","romaji":"Ashita no kaigi wa kantan ni shimasu."},{"jp":"健康的な食事にします。","en":"I will choose a healthy meal.","romaji":"Kenkou-teki na shokuji ni shimasu."}],"example":"静かにします。","exampleMeaning":"I will be quiet."},{"pattern":"な-Adjective に なります (na-Adjective ni narimasu)","meaning":"Express a change or transformation into a state described by the な-adjective.","formation":"な-Adjective (remove な) + に + なります","examples":[{"jp":"この部屋は静かになります。","en":"This room becomes quiet.","romaji":"Kono heya wa shizuka ni narimasu."},{"jp":"彼女はきれいになります。","en":"She becomes beautiful.","romaji":"Kanojo wa kirei ni narimasu."},{"jp":"彼は元気になります。","en":"He becomes energetic.","romaji":"Kare wa genki ni narimasu."},{"jp":"町はにぎやかになります。","en":"The town becomes lively.","romaji":"Machi wa nigiyaka ni narimasu."}],"example":"この部屋は静かになります。","exampleMeaning":"This room becomes quiet."},{"pattern":"Noun か Noun か～","meaning":"Expresses choice or alternatives; 'either', 'or'.","formation":"Noun1 + か + Noun2 + か～","examples":[{"jp":"今日、映画を見るか、散歩するかどちらにしますか？","en":"Will we watch a movie or go for a walk today?","romaji":"Kyou, eiga wo miru ka, sanpo suru ka dochira ni shimasu ka?"},{"jp":"コーヒーか紅茶か、一つだけ選んでください。","en":"Please choose only one, either coffee or tea.","romaji":"Koohii ka koucha ka, hitotsu dake erande kudasai."},{"jp":"電車かバスを使って、学校に行くつもりです。","en":"I plan to go to school using either the train or the bus.","romaji":"Densha ka basu o tsukatte, gakkou ni iku tsumori desu."},{"jp":"週末は山に登るか海に行くか、まだ決めていません。","en":"I haven't decided whether to climb the mountain or go to the beach this weekend.","romaji":"Shuumatsu wa yama ni noboru ka umi ni iku ka, mada kimete imasen."}],"example":"今日、映画を見るか、散歩するかどちらにしますか？","exampleMeaning":"Will we watch a movie or go for a walk today?"},{"pattern":"Noun が できます","meaning":"Express the ability to do something.","formation":"Noun + が + できます","examples":[{"jp":"英語ができます。","en":"I can speak English.","romaji":"Eigo ga dekimasu."},{"jp":"料理ができます。","en":"I can cook.","romaji":"Ryouri ga dekimasu."},{"jp":"彼は泳ぎができます。","en":"He can swim.","romaji":"Kare wa oyogi ga dekimasu."},{"jp":"彼女はピアノができます。","en":"She can play the piano.","romaji":"Kanojo wa piano ga dekimasu."}],"example":"英語ができます。","exampleMeaning":"I can speak English."},{"pattern":"Noun がほしいです (〜ga hoshii desu)","meaning":"Express a desire or wanting something; 'I want', 'I would like'.","formation":"Noun + が + ほしいです","examples":[{"jp":"新しい車がほしいです。","en":"I want a new car.","romaji":"Atarashii kuruma ga hoshii desu."},{"jp":"コーヒーがほしいです。","en":"I would like some coffee.","romaji":"Koohii ga hoshii desu."},{"jp":"彼女は花がほしいです。","en":"She wants flowers.","romaji":"Kanojo wa hana ga hoshii desu."},{"jp":"友達がほしいです。","en":"I want a friend.","romaji":"Tomodachi ga hoshii desu."}],"example":"新しい車がほしいです。","exampleMeaning":"I want a new car."},{"pattern":"Noun から Noun まで","meaning":"Expresses a range; 'from...to', 'between...and'.","formation":"Noun1 + から + Noun2 + まで","examples":[{"jp":"朝9時から午後5時まで働きます。","en":"I work from 9 AM to 5 PM.","romaji":"Asa ku-ji kara gogo go-ji made hatarakimasu."},{"jp":"東京から大阪まで電車で行く。","en":"I will go by train from Tokyo to Osaka.","romaji":"Toukyou kara Osaka made densha de iku."},{"jp":"地下鉄は午前6時から深夜まで運行しています。","en":"The subway runs from 6 AM until midnight.","romaji":"Chikatetsu wa gozen roku-ji kara shin'ya made unkou shite imasu."},{"jp":"月曜日から金曜日まで学校に通います。","en":"I attend school from Monday to Friday.","romaji":"Getsuyoubi kara Kinyoubi made gakkou ni kayoimasu."}],"example":"朝9時から午後5時まで働きます。","exampleMeaning":"I work from 9 AM to 5 PM."},{"pattern":"Noun くらい～","meaning":"Express the extent or degree of something; 'about', 'approximately', 'at least'.","formation":"Noun + くらい","examples":[{"jp":"この本は三百ページくらいあります。","en":"This book has about 300 pages.","romaji":"Kono hon wa sanbyaku peeji kurai arimasu."},{"jp":"彼の家まで歩いて20分くらいかかります。","en":"It takes about 20 minutes to walk to his house.","romaji":"Kare no ie made aruite nijuppun kurai kakarimasu."},{"jp":"明日は暑くて、30度くらいになるでしょう。","en":"Tomorrow will be hot, about 30 degrees.","romaji":"Ashita wa atsukute, sanjuu-do kurai ni naru deshou."},{"jp":"この料理を作るのに、材料は500円くらい必要です。","en":"You need about 500 yen worth of ingredients to make this dish.","romaji":"Kono ryouri o tsukuru no ni, zairyou wa gohyaku-en kurai hitsuyou desu."}],"example":"この本は三百ページくらいあります。","exampleMeaning":"This book has about 300 pages."},{"pattern":"Noun ぐらい～","meaning":"Express an approximate amount or degree; 'about', 'approximately'.","formation":"Noun + ぐらい","examples":[{"jp":"一日中勉強したので、１０時間ぐらい勉強しました。","en":"I studied all day, so I studied for about 10 hours.","romaji":"Ichinichijuu benkyou shita node, juu-jikan gurai benkyou shimashita."},{"jp":"この本は１００ページぐらいある。","en":"This book has about 100 pages.","romaji":"Kono hon wa hyaku peeji gurai aru."},{"jp":"彼は果物を５個ぐらい食べました。","en":"He ate about 5 pieces of fruit.","romaji":"Kare wa kudamono o go-ko gurai tabemashita."},{"jp":"駅から家まで歩いて２０分ぐらいかかります。","en":"It takes about 20 minutes to walk from the station to my house.","romaji":"Eki kara ie made aruite nijuppun gurai kakarimasu."}],"example":"一日中勉強したので、１０時間ぐらい勉強しました。","exampleMeaning":"I studied all day, so I studied for about 10 hours."},{"pattern":"Noun ごろ～ (Noun + goro～)","meaning":"Expresses 'around' or 'about' a certain time or age.","formation":"Noun + ごろ","examples":[{"jp":"昼ごろに電話してください。","en":"Please call me around noon.","romaji":"Hiru goro ni denwa shite kudasai."},{"jp":"彼は10歳ごろに日本に来ました。","en":"He came to Japan around the age of 10.","romaji":"Kare wa juu-sai goro ni Nihon ni kimashita."},{"jp":"午後３時ごろに会いましょう。","en":"Let's meet around 3 PM.","romaji":"Gogo san-ji goro ni aimashou."},{"jp":"昨日の夜8時ごろに帰りました。","en":"I returned home last night around 8 o'clock.","romaji":"Kinou no yoru hachi-ji goro ni kaerimashita."}],"example":"昼ごろに電話してください。","exampleMeaning":"Please call me around noon."},{"pattern":"Noun だけ〜 (〜dake)","meaning":"Indicates 'only', 'just', or 'merely'.","formation":"Noun + だけ, Verb-casual + だけ, い-Adjective + だけ, な-Adjective-な + だけ","examples":[{"jp":"コーヒーだけ飲んで、帰りました。","en":"I only drank coffee and went home.","romaji":"Koohii dake nonde, kaerimashita."},{"jp":"この本は二十ページだけ読んだ。","en":"I only read twenty pages of this book.","romaji":"Kono hon wa nijuu peeji dake yonda."},{"jp":"彼女はとても速いですが、走るだけでなく、考えるのも速いです。","en":"She is very fast, not only at running but also at thinking.","romaji":"Kanojo wa totemo hayai desu ga, hashiru dake denaku, kangaeru no mo hayai desu."},{"jp":"この部屋は寝るだけの場所です。","en":"This room is a place only for sleeping.","romaji":"Kono heya wa neru dake no basho desu."}],"example":"コーヒーだけ飲んで、帰りました。","exampleMeaning":"I only drank coffee and went home."},{"pattern":"Nounで～","meaning":"Indicate a place or means for an action or situation; 'at, in, on', 'using', or 'by means of'.","formation":"Noun + で","examples":[{"jp":"図書館で勉強します。","en":"I study at the library.","romaji":"Toshokan de benkyou shimasu."},{"jp":"バスで学校に行きます。","en":"I go to school by bus.","romaji":"Basu de gakkou ni ikimasu."},{"jp":"鉛筆で書きました。","en":"I wrote it using a pencil.","romaji":"Enpitsu de kakimashita."},{"jp":"英語で話しましょう。","en":"Let's talk in English.","romaji":"Eigo de hanashimashou."}],"example":"図書館で勉強します。","exampleMeaning":"I study at the library."},{"pattern":"Noun と～","meaning":"Express 'with', 'and' or 'together with' when connecting nouns.","formation":"Noun1 + と + Noun2","examples":[{"jp":"リンゴとバナナを買いました。","en":"I bought apples and bananas.","romaji":"Ringo to banana wo kaimashita."},{"jp":"友達と映画を見に行きます。","en":"I will go to watch a movie with my friend.","romaji":"Tomodachi to eiga wo mi ni ikimasu."},{"jp":"父と母と一緒に旅行しました。","en":"I traveled together with my father and mother.","romaji":"Chichi to haha to issho ni ryokou shimashita."},{"jp":"彼と彼女は結婚しました。","en":"He and she got married.","romaji":"Kare to kanojo wa kekkon shimashita."}],"example":"リンゴとバナナを買いました。","exampleMeaning":"I bought apples and bananas."},{"pattern":"Noun に～","meaning":"Express a specific direction, target or purpose; 'to', 'toward', 'for'.","formation":"Noun + に","examples":[{"jp":"彼女にプレゼントをあげました。","en":"I gave a present to her.","romaji":"Kanojo ni purezento wo agemashita."},{"jp":"日本に行きます。","en":"I am going to Japan.","romaji":"Nihon ni ikimasu."},{"jp":"6時に集合しましょう。","en":"Let's meet at 6 o'clock.","romaji":"Roku-ji ni shuugou shimashou."},{"jp":"友達に手紙を書きます。","en":"I will write a letter to my friend.","romaji":"Tomodachi ni tegami wo kakimasu."}],"example":"彼女にプレゼントをあげました。","exampleMeaning":"I gave a present to her."},{"pattern":"Noun に 帰ります","meaning":"Express going back or returning to a place: 'to return to', 'to go back to'.","formation":"Noun + に + 帰ります","examples":[{"jp":"夏休みが終わったら、学校に帰ります。","en":"When summer vacation ends, I'll go back to school.","romaji":"Natsuyasumi ga owattara, gakkou ni kaerimasu."},{"jp":"買い物を終えたら、家に帰ります。","en":"After finishing shopping, I will go back home.","romaji":"Kaimono o oetara, ie ni kaerimasu."},{"jp":"今週末、実家に帰ります。","en":"I'm going back to my parents' home this weekend.","romaji":"Konshuumatsu, jikka ni kaerimasu."},{"jp":"友達と旅行に行ったあと、東京に帰ります。","en":"After traveling with my friend, I'll return to Tokyo.","romaji":"Tomodachi to ryokou ni itta ato, Toukyou ni kaerimasu."}],"example":"夏休みが終わったら、学校に帰ります。","exampleMeaning":"When summer vacation ends, I'll go back to school."},{"pattern":"Noun に します","meaning":"Express a choice or decision; 'choose', 'decide on'.","formation":"Noun + に します","examples":[{"jp":"今日の昼ご飯は寿司にします。","en":"I'll choose sushi for today's lunch.","romaji":"Kyou no hirugohan wa sushi ni shimasu."},{"jp":"この靴を買うか迷っていますが、赤い色の方にします。","en":"I was hesitating about which shoes to buy, but I'll go with the red ones.","romaji":"Kono kutsu wo kau ka mayotteimasu ga, akai iro no hou ni shimasu."},{"jp":"休みの日に何をするか決めた。映画館に行くことにします。","en":"I've decided what to do on my day off. I'll go to the movie theater.","romaji":"Yasumi no hi ni nani wo suru ka kimeta. Eigakan ni iku koto ni shimasu."},{"jp":"フランス語とスペイン語のどちらを勉強するか悩んだが、フランス語にします。","en":"I was torn between studying French and Spanish, but I decided on French.","romaji":"Furansugo to Supeingo no dochira wo benkyou suru ka nayanda ga, Furansugo ni shimasu."}],"example":"今日の昼ご飯は寿司にします。","exampleMeaning":"I'll choose sushi for today's lunch."},{"pattern":"Noun に なります","meaning":"Expresses change or becoming something; 'to become', 'to turn into', 'to be'.","formation":"Noun + に + なります","examples":[{"jp":"彼は医者になります。","en":"He will become a doctor.","romaji":"Kare wa isha ni narimasu."},{"jp":"この茶色の葉が赤になります。","en":"These brown leaves will turn red.","romaji":"Kono chairo no ha ga aka ni narimasu."},{"jp":"料理が冷めたら、美味しくなくなります。","en":"When the dish cools down, it becomes less delicious.","romaji":"Ryouri ga sametara, oishikunaku narimasu."},{"jp":"来年、東京オリンピックになります。","en":"Next year, it will be the Tokyo Olympics.","romaji":"Rainen, Toukyou Orinpikku ni narimasu."}],"example":"彼は医者になります。","exampleMeaning":"He will become a doctor."},{"pattern":"Noun に 来ます","meaning":"Used to express coming to a place.","formation":"Noun + に + 来ます (kimasu)","examples":[{"jp":"友達が私の家に来ます。","en":"My friend will come to my house.","romaji":"Tomodachi ga watashi no ie ni kimasu."},{"jp":"今晩、父が駅に迎えに来ます。","en":"Tonight, my father will come to pick me up at the station.","romaji":"Konban, chichi ga eki ni mukae ni kimasu."},{"jp":"明日、先生が学校に来ます。","en":"Tomorrow, the teacher will come to school.","romaji":"Ashita, sensei ga gakkou ni kimasu."},{"jp":"有名な歌手がこの街に来ます。","en":"A famous singer will come to this town.","romaji":"Yuumei na kashu ga kono machi ni kimasu."}],"example":"友達が私の家に来ます。","exampleMeaning":"My friend will come to my house."},{"pattern":"Noun に 行きます","meaning":"Used to express going to a location.","formation":"Noun + に + 行きます","examples":[{"jp":"学校に行きます。","en":"I will go to school.","romaji":"Gakkou ni ikimasu."},{"jp":"明日、スーパーに行きます。","en":"I will go to the supermarket tomorrow.","romaji":"Ashita, suupaa ni ikimasu."},{"jp":"週末に映画館に行きます。","en":"I will go to the movie theater on the weekend.","romaji":"Shuumatsu ni eigakan ni ikimasu."},{"jp":"夏休みに海に行きます。","en":"I will go to the sea during the summer vacation.","romaji":"Natsu yasumi ni umi ni ikimasu."}],"example":"学校に行きます。","exampleMeaning":"I will go to school."},{"pattern":"Noun の あとで","meaning":"Expresses the order of events; 'after', 'later than'.","formation":"Noun + の + あとで","examples":[{"jp":"朝ご飯のあとで、歯を磨きます。","en":"After breakfast, I brush my teeth.","romaji":"Asagohan no atode, ha wo migakimasu."},{"jp":"映画のあとで、レストランで夕食を食べました。","en":"After the movie, we ate dinner at a restaurant.","romaji":"Eiga no atode, resutoran de yuushoku o tabemashita."},{"jp":"会議のあとで、上司と話し合います。","en":"I will discuss with my boss after the meeting.","romaji":"Kaigi no atode, joushi to hanashiaimasu."},{"jp":"晩ご飯のあとで、散歩に行きました。","en":"After dinner, I went for a walk.","romaji":"Bangohan no atode, sanpo ni ikimashita."}],"example":"朝ご飯のあとで、歯を磨きます。","exampleMeaning":"After breakfast, I brush my teeth."},{"pattern":"Noun の 前に","meaning":"Used to describe a location or position 'in front of' a noun.","formation":"Noun + の + 前に","examples":[{"jp":"駅の前にコンビニがあります。","en":"There is a convenience store in front of the station.","romaji":"Eki no mae ni konbini ga arimasu."},{"jp":"家の前に車を止めてください。","en":"Please park the car in front of the house.","romaji":"Ie no mae ni kuruma wo tomete kudasai."},{"jp":"私の前に彼が立っていました。","en":"He was standing in front of me.","romaji":"Watashi no mae ni kare ga tatte imashita."},{"jp":"ホテルの前にタクシーが来た。","en":"A taxi came in front of the hotel.","romaji":"Hoteru no mae ni takushii ga kita."}],"example":"駅の前にコンビニがあります。","exampleMeaning":"There is a convenience store in front of the station."},{"pattern":"Noun は～ (Noun wa〜)","meaning":"Used to mark the topic of a sentence; 'as for', 'speaking of'.","formation":"Noun + は","examples":[{"jp":"私は日本の料理が好きです。","en":"As for me, I like Japanese cuisine.","romaji":"Watashi wa Nihon no ryouri ga suki desu."},{"jp":"彼は英語が上手です。","en":"As for him, he is good at English.","romaji":"Kare wa eigo ga jouzu desu."},{"jp":"この本は面白いです。","en":"As for this book, it's interesting.","romaji":"Kono hon wa omoshiroi desu."},{"jp":"今日は暑いですね。","en":"Speaking of today, it's hot, isn't it?","romaji":"Kyou wa atsui desu ne."}],"example":"私は日本の料理が好きです。","exampleMeaning":"As for me, I like Japanese cuisine."},{"pattern":"Noun も〜","meaning":"Indicates that the action or state is the same for multiple items or people; 'also', 'as well'.","formation":"Noun + も","examples":[{"jp":"私も日本語を勉強しています。","en":"I am also studying Japanese.","romaji":"Watashi mo nihongo wo benkyou shiteimasu."},{"jp":"彼もケーキが好きです。","en":"He also likes cake.","romaji":"Kare mo keeki ga suki desu."},{"jp":"東京も大阪も観光スポットがたくさんあります。","en":"There are many tourist spots in both Tokyo and Osaka.","romaji":"Toukyou mo Oosaka mo kankou supotto ga takusan arimasu."},{"jp":"この映画もあの映画も面白かった。","en":"Both this movie and that movie were interesting.","romaji":"Kono eiga mo ano eiga mo omoshirokatta."}],"example":"私も日本語を勉強しています。","exampleMeaning":"I am also studying Japanese."},{"pattern":"Noun や Noun など～","meaning":"Lists items or examples but not exhaustively; 'such as', 'like', 'and so on'.","formation":"Noun1 + や + Noun2 + など","examples":[{"jp":"彼は野菜や果物などを食べるのが好きです。","en":"He likes to eat things like vegetables and fruits.","romaji":"Kare wa yasai ya kudamono nado o taberu no ga suki desu."},{"jp":"日本の都市や東京、大阪などに行きたいです。","en":"I want to go to Japanese cities such as Tokyo, Osaka, and so on.","romaji":"Nihon no toshi ya Toukyou, Oosaka nado ni ikitai desu."},{"jp":"彼女は猫や犬など動物が好きです。","en":"She likes animals like cats, dogs, and so on.","romaji":"Kanojo wa neko ya inu nado doubutsu ga suki desu."},{"jp":"この本屋では漫画や小説などたくさんの本が売られています。","en":"In this bookstore, many books such as manga and novels are sold.","romaji":"Kono honya de wa manga ya shousetsu nado takusan no hon ga urarete imasu."}],"example":"彼は野菜や果物などを食べるのが好きです。","exampleMeaning":"He likes to eat things like vegetables and fruits."},{"pattern":"Noun を〜 (Noun wo〜)","meaning":"Indicates the direct object of a verb.","formation":"Noun + を + Verb","examples":[{"jp":"私は本を読みます。","en":"I read a book.","romaji":"Watashi wa hon wo yomimasu."},{"jp":"彼はケーキを食べました。","en":"He ate a cake.","romaji":"Kare wa keeki wo tabemashita."},{"jp":"母はコーヒーを飲むのが好きです。","en":"My mother likes to drink coffee.","romaji":"Haha wa koohii wo nomu no ga suki desu."},{"jp":"友達が私のペンを使いました。","en":"My friend used my pen.","romaji":"Tomodachi ga watashi no pen wo tsukaimashita."}],"example":"私は本を読みます。","exampleMeaning":"I read a book."},{"pattern":"Verb た あとで","meaning":"Indicates an action that takes place after another action.","formation":"Verb-た form + あとで","examples":[{"jp":"宿題をしたあとで、テレビを見ました。","en":"After doing my homework, I watched TV.","romaji":"Shukudai wo shita ato de, terebi wo mimashita."},{"jp":"朝ごはんを食べたあとで、歯を磨きます。","en":"After eating breakfast, I brush my teeth.","romaji":"Asagohan wo tabeta ato de, ha wo migakimasu."},{"jp":"仕事が終わったあとで、ジムに行く予定です。","en":"After finishing work, I plan to go to the gym.","romaji":"Shigoto ga owatta ato de, jimu ni iku yotei desu."},{"jp":"映画を見たあとで、カフェでコーヒーを飲みました。","en":"After watching the movie, I drank coffee at a cafe.","romaji":"Eiga wo mita ato de, kafe de koohii wo nomimashita."}],"example":"宿題をしたあとで、テレビを見ました。","exampleMeaning":"After doing my homework, I watched TV."},{"pattern":"Verb たいです","meaning":"Express desire or want to do something; 'I want to', 'I would like to'.","formation":"る-Verb: Remove る and add たいです, う-Verb: Replace the final verb character with the ～い form and add たいです, Exception: する becomes したいです","examples":[{"jp":"私は寿司を食べたいです。","en":"I want to eat sushi.","romaji":"Watashi wa sushi wo tabetai desu."},{"jp":"彼は日本に行きたいです。","en":"He wants to go to Japan.","romaji":"Kare wa Nihon ni ikitai desu."},{"jp":"彼女は英語を勉強したいです。","en":"She wants to study English.","romaji":"Kanojo wa eigo wo benkyou shitai desu."},{"jp":"子供たちは遊びたいです。","en":"The children want to play.","romaji":"Kodomo-tachi wa asobitai desu."}],"example":"私は寿司を食べたいです。","exampleMeaning":"I want to eat sushi."},{"pattern":"Verb て～ (Verb + te～)","meaning":"A verb conjugation that connects actions or states.","formation":"Verb (Group 1) - Replace last syllable with 〜て, Verb (Group 2) - Replace 'る' with 〜て, Verb (Group 3) - する becomes して, くる becomes きて","examples":[{"jp":"コーヒーを飲んで、出かけます。","en":"After drinking coffee, I will go out.","romaji":"Koohii o nonde, dekakemasu."},{"jp":"買い物をして、家に帰りましょう。","en":"Let's go shopping and then go home.","romaji":"Kaimono o shite, ie ni kaerimashou."},{"jp":"宿題をして、寝ます。","en":"After doing my homework, I will sleep.","romaji":"Shukudai o shite, nemasu."},{"jp":"友達を待って、一緒に映画を見に行きます。","en":"I will wait for my friend and go watch a movie together.","romaji":"Tomodachi o matte, issho ni eiga o mini ikimasu."}],"example":"コーヒーを飲んで、出かけます。","exampleMeaning":"After drinking coffee, I will go out."},{"pattern":"Verb て います","meaning":"Express ongoing action or state; 'is doing', 'is doing (continuous)', 'has been doing'.","formation":"Verb て-form + います","examples":[{"jp":"彼女は今ピアノを弾いています。","en":"She is playing the piano now.","romaji":"Kanojo wa ima piano wo hiite imasu."},{"jp":"私たちは日本語を勉強しています。","en":"We are studying Japanese.","romaji":"Watashitachi wa nihongo wo benkyou shiteimasu."},{"jp":"彼は映画を見ています。","en":"He is watching a movie.","romaji":"Kare wa eiga wo miteimasu."},{"jp":"入っていますので、お待ちください。","en":"I am in, so please wait.","romaji":"Haitteimasu node, omachi kudasai."}],"example":"彼女は今ピアノを弾いています。","exampleMeaning":"She is playing the piano now."},{"pattern":"Verb てから～ (〜te kara)","meaning":"Express a sequence of actions or events; 'after', 'since', 'once'.","formation":"Verb-て形 + から","examples":[{"jp":"宿題をしてから、テレビを見ました。","en":"I watched TV after doing my homework.","romaji":"Shukudai wo shite kara, terebi wo mimashita."},{"jp":"食べてから、歯を磨きましょう。","en":"Let's brush our teeth after eating.","romaji":"Tabete kara, ha wo migakimashou."},{"jp":"仕事が終わってから、友達と飲みに行きます。","en":"I will go drinking with my friends after work is done.","romaji":"Shigoto ga owatte kara, tomodachi to nomi ni ikimasu."},{"jp":"学校が終わってから、図書館で勉強します。","en":"I will study in the library after school is over.","romaji":"Gakkou ga owatte kara, toshokan de benkyou shimasu."}],"example":"宿題をしてから、テレビを見ました。","exampleMeaning":"I watched TV after doing my homework."},{"pattern":"Verb て ください (Verb-te kudasai)","meaning":"A request or command; 'please do'.","formation":"Verb-て form + ください","examples":[{"jp":"ドアを開けてください。","en":"Please open the door.","romaji":"Doa wo akete kudasai."},{"jp":"電話番号を教えてください。","en":"Please tell me your phone number.","romaji":"Denwa bangou wo oshiete kudasai."},{"jp":"ゆっくり話してください。","en":"Please speak slowly.","romaji":"Yukkuri hanashite kudasai."},{"jp":"コーヒーを一つ持ってきてください。","en":"Please bring me a coffee.","romaji":"Koohii wo hitotsu motte kite kudasai."}],"example":"ドアを開けてください。","exampleMeaning":"Please open the door."},{"pattern":"Verb ないで ください (〜naide kudasai)","meaning":"Used to make a polite request for someone not to do something; 'please don't'.","formation":"Verb-ない-form + で ください","examples":[{"jp":"タバコを吸わないでください。","en":"Please don't smoke.","romaji":"Tabako wo suwanaide kudasai."},{"jp":"ここで走らないでください。","en":"Please don't run here.","romaji":"Koko de hashiranaide kudasai."},{"jp":"大きな声で話さないでください。","en":"Please don't speak loudly.","romaji":"Ookina koe de hanasanaide kudasai."},{"jp":"写真を撮らないでください。","en":"Please don't take photos.","romaji":"Shashin wo toranaide kudasai."}],"example":"タバコを吸わないでください。","exampleMeaning":"Please don't smoke."},{"pattern":"Noun に 戻ります","meaning":"Expresses the action of returning to a previous state, place, or condition.","formation":"Noun + に + 戻ります","examples":[{"jp":"冷蔵庫に入れると、溶けたアイスクリームは固体に戻ります。","en":"When put in the refrigerator, the melted ice cream returns to its solid state.","romaji":"Reizouko ni ireru to, toketa aisukuriimu wa kotai ni modorimasu."},{"jp":"休暇が終わったら、仕事に戻ります。","en":"When the vacation ends, I will return to work.","romaji":"Kyuuka ga owattara, shigoto ni modorimasu."},{"jp":"リモートワークが終わった後、元のオフィスに戻ります。","en":"After remote work is over, we will return to our original office.","romaji":"Rimooto waaku ga owatta ato, moto no ofisu ni modorimasu."},{"jp":"外国で勉強した後、日本に帰ります。","en":"After studying abroad, I will return to Japan.","romaji":"Gaikoku de benkyou shita ato, Nihon ni kaerimasu."}],"example":"冷蔵庫に入れると、溶けたアイスクリームは固体に戻ります。","exampleMeaning":"When put in the refrigerator, the melted ice cream returns to its solid state."},{"pattern":"Verb に 来ます","meaning":"Expresses the purpose of coming to a place; 'come to (do something)'.","formation":"Verb (ます-stem) + に + 来ます","examples":[{"jp":"友達に会いに来ました。","en":"I came to meet my friend.","romaji":"Tomodachi ni ai ni kimashita."},{"jp":"映画を見に来ました。","en":"I came to watch a movie.","romaji":"Eiga wo mi ni kimashita."},{"jp":"先生に質問しに来ました。","en":"I came to ask the teacher a question.","romaji":"Sensei ni shitsumon shi ni kimashita."},{"jp":"買い物をしに来ました。","en":"I came to go shopping.","romaji":"Kaimono wo shi ni kimashita."}],"example":"友達に会いに来ました。","exampleMeaning":"I came to meet my friend."},{"pattern":"Verb に 行きます","meaning":"To go (somewhere) in order to do an action.","formation":"Verb (ます-stem) + に + 行きます","examples":[{"jp":"公園に遊びに行きます。","en":"I will go to the park to play.","romaji":"Kouen ni asobi ni ikimasu."},{"jp":"図書館に勉強しに行きます。","en":"I will go to the library to study.","romaji":"Toshokan ni benkyou shi ni ikimasu."},{"jp":"スーパーに買い物に行きます。","en":"I will go to the supermarket to do some shopping.","romaji":"Suupaa ni kaimono ni ikimasu."},{"jp":"映画館に映画を見に行きます。","en":"I will go to the movie theater to watch a movie.","romaji":"Eigakan ni eiga wo mi ni ikimasu."}],"example":"公園に遊びに行きます。","exampleMeaning":"I will go to the park to play."},{"pattern":"Verb ましょう","meaning":"Making a suggestion or invitation; 'let's' or 'shall we'.","formation":"Verb (ます-stem) + ましょう","examples":[{"jp":"一緒に映画を見ましょう。","en":"Let's watch a movie together.","romaji":"Issho ni eiga wo mimashou."},{"jp":"散歩しましょう。","en":"Let's take a walk.","romaji":"Sanpo shimashou."},{"jp":"今晩、食事に行きましょう。","en":"Let's go out for dinner tonight.","romaji":"Konban, shokuji ni ikimashou."},{"jp":"明日勉強しましょう。","en":"Let's study tomorrow.","romaji":"Ashita benkyou shimashou."}],"example":"一緒に映画を見ましょう。","exampleMeaning":"Let's watch a movie together."},{"pattern":"Verb ましょうか。 (〜mashou ka.)","meaning":"Used to make a polite suggestion or offer help; 'shall we', 'should we', 'do you want me to'.","formation":"Verb (ます-stem) + ましょうか","examples":[{"jp":"一緒に映画を見に行きましょうか。","en":"Shall we go see a movie together?","romaji":"Issho ni eiga wo mi ni ikimashou ka."},{"jp":"コーヒーをもう一杯飲みましょうか。","en":"Should we have another cup of coffee?","romaji":"Koohii wo mou ippai nomimashou ka."},{"jp":"あなたの荷物を持ちましょうか。","en":"Do you want me to carry your luggage?","romaji":"Anata no nimotsu wo mochimashou ka."},{"jp":"窓を開けましょうか。","en":"Shall I open the window?","romaji":"Mado wo akemashou ka."}],"example":"一緒に映画を見に行きましょうか。","exampleMeaning":"Shall we go see a movie together?"},{"pattern":"Verb ませんか。 (Verb-masenka)","meaning":"An invitation or suggestion; 'won't you', 'why don't you', 'shall we'.","formation":"Verb (ます-form) + ませんか","examples":[{"jp":"一緒に映画を見ませんか。","en":"Won't you watch a movie together with me?","romaji":"Issho ni eiga wo mimasenka."},{"jp":"明日のパーティーに参加しませんか。","en":"Why don't you join tomorrow's party?","romaji":"Ashita no paatii ni sanka shimasenka."},{"jp":"週末にピクニックに行きませんか。","en":"Shall we go for a picnic on the weekend?","romaji":"Shuumatsu ni pikunikku ni ikimasenka."},{"jp":"一緒に勉強しませんか。","en":"How about studying together?","romaji":"Issho ni benkyou shimasenka."}],"example":"一緒に映画を見ませんか。","exampleMeaning":"Won't you watch a movie together with me?"},{"pattern":"Verb ること～ (〜ru koto)","meaning":"Express an action or event as a noun; 'the act of', 'doing'.","formation":"Verb (dictionary form) + こと","examples":[{"jp":"泳ぐことが大好きです。","en":"I love swimming.","romaji":"Oyogu koto ga daisuki desu."},{"jp":"日本語を勉強することは楽しいです。","en":"Studying Japanese is fun.","romaji":"Nihongo wo benkyou suru koto wa tanoshii desu."},{"jp":"友達と話すことがストレスを軽減します。","en":"Talking with friends reduces stress.","romaji":"Tomodachi to hanasu koto ga sutoresu wo keigen shimasu."},{"jp":"彼は歌うことが得意です。","en":"He is good at singing.","romaji":"Kare wa utau koto ga tokui desu."}],"example":"泳ぐことが大好きです。","exampleMeaning":"I love swimming."},{"pattern":"Verb る こと が できます","meaning":"Express the potential form, or the ability to do something.","formation":"Verb (dictionary form) + ことができます","examples":[{"jp":"この問題を解くことができます。","en":"I can solve this problem.","romaji":"Kono mondai o toku koto ga dekimasu."},{"jp":"彼は英語を話すことができます。","en":"He can speak English.","romaji":"Kare wa eigo o hanasu koto ga dekimasu."},{"jp":"私は高い所に登ることができません。","en":"I can't climb to high places.","romaji":"Watashi wa takai tokoro ni noboru koto ga dekimasen."},{"jp":"彼女はピアノを弾くことができます。","en":"She can play the piano.","romaji":"Kanojo wa piano o hiku koto ga dekimasu."}],"example":"この問題を解くことができます。","exampleMeaning":"I can solve this problem."},{"pattern":"Verb る こと ができる","meaning":"Expresses the potential form; 'can', 'be able to', 'is possible'.","formation":"Verb (dictionary form) + ことができる","examples":[{"jp":"この問題を解くことができる？","en":"Can you solve this problem?","romaji":"Kono mondai o toku koto ga dekiru?"},{"jp":"彼は泳ぐことができます。","en":"He can swim.","romaji":"Kare wa oyogu koto ga dekimasu."},{"jp":"日本に行くことができて、とても嬉しいです。","en":"I'm very happy that I can go to Japan.","romaji":"Nihon ni iku koto ga dekite, totemo ureshii desu."},{"jp":"彼女はピアノを弾くことができます。","en":"She can play the piano.","romaji":"Kanojo wa piano o hiku koto ga dekimasu."}],"example":"この問題を解くことができる？","exampleMeaning":"Can you solve this problem?"},{"pattern":"Verb る の～ (Verb + ru + no~)","meaning":"Used to express the purpose or reason in casual speech, or nominalize the verb with の.","formation":"Verb (dictionary form) + の (casual)","examples":[{"jp":"買い物をするために、銀行でお金をおろすの。","en":"I'm withdrawing money at the bank so I can go shopping.","romaji":"Kaimono o suru tame ni, ginkou de okane o orosu no."},{"jp":"友達にプレゼントをあげるので、ケーキを焼くの。","en":"I'm baking a cake because I'm giving my friend a present.","romaji":"Tomodachi ni purezento o ageru node, keeki o yaku no."},{"jp":"ダイエットを始めるので、ジムに入会するの。","en":"I’m joining a gym since I'm starting a diet.","romaji":"Daietto o hajimeru node, jimu ni nyuukai suru no."},{"jp":"軽い食事がいいので、サラダを作るの。","en":"I'm making a salad because I want a light meal.","romaji":"Karui shokuji ga ii node, sarada o tsukuru no."}],"example":"買い物をするために、銀行でお金をおろすの。","exampleMeaning":"I'm withdrawing money at the bank so I can go shopping."},{"pattern":"Verb る 前に","meaning":"Used to express 'before' in a sense of an action must be done before another action or event.","formation":"Verb (dictionary form) + 前に","examples":[{"jp":"出かける前に、部屋を掃除してください。","en":"Please clean the room before leaving.","romaji":"Dekakeru mae ni, heya o souji shite kudasai."},{"jp":"寝る前に、歯を磨きます。","en":"I brush my teeth before going to bed.","romaji":"Neru mae ni, ha o migakimasu."},{"jp":"雨が降る前に、洗濯物を取り込むこと。","en":"Take in the laundry before it rains.","romaji":"Ame ga furu mae ni, sentakumono o torikomu koto."},{"jp":"会議が始まる前に、資料を準備しましょう。","en":"Let's prepare the documents before the meeting starts.","romaji":"Kaigi ga hajimaru mae ni, shiryou o junbi shimashou."}],"example":"出かける前に、部屋を掃除してください。","exampleMeaning":"Please clean the room before leaving."},{"pattern":"あまり～ありません","meaning":"Express 'not very', 'not much', or 'not really' when describing a negative state or situation.","formation":"あまり + Verb-ないform + ありません / あまり + い-Adjective-く ありません / あまり + な-Adjective・Noun じゃありません","examples":[{"jp":"彼はあまり疲れていません。","en":"He is not really tired.","romaji":"Kare wa amari tsukareteimasen."},{"jp":"彼女はあまり早くないですよ。","en":"She is not very fast.","romaji":"Kanojo wa amari hayakunai desu yo."},{"jp":"私はあまり勉強しないです。","en":"I don't study very much.","romaji":"Watashi wa amari benkyou shinai desu."},{"jp":"あまりお金がありません。","en":"I don't have much money.","romaji":"Amari okane ga arimasen."}],"example":"彼はあまり疲れていません。","exampleMeaning":"He is not really tired."},{"pattern":"あまり～ないです","meaning":"Express 'not really' or 'not very'; used to soften a negative statement.","formation":"あまり + Verb-ないform + です / あまり + い-Adjective-くない + です / あまり + な-Adjective-じゃない + です","examples":[{"jp":"あまり食べないです。","en":"I don't really eat much.","romaji":"Amari tabenai desu."},{"jp":"この映画はあまり面白くないです。","en":"This movie is not really interesting.","romaji":"Kono eiga wa amari omoshirokunai desu."},{"jp":"彼はあまり親切じゃないです。","en":"He is not very kind.","romaji":"Kare wa amari shinsetsu ja nai desu."},{"jp":"私はあまり日本語が上手じゃないです。","en":"I am not very good at Japanese.","romaji":"Watashi wa amari nihongo ga jouzu ja nai desu."}],"example":"あまり食べないです。","exampleMeaning":"I don't really eat much."},{"pattern":"～あります (〜arimasu)","meaning":"Indicate possession or existence of inanimate objects; 'there is', 'there are'.","formation":"Object + が + あります","examples":[{"jp":"教室に机があります。","en":"There is a desk in the classroom.","romaji":"Kyoushitsu ni tsukue ga arimasu."},{"jp":"この公園にたくさんの花があります。","en":"There are many flowers in this park.","romaji":"Kono kouen ni takusan no hana ga arimasu."},{"jp":"駅の近くにコンビニがあります。","en":"There is a convenience store near the station.","romaji":"Eki no chikaku ni konbini ga arimasu."},{"jp":"家の中に古いテレビがあります。","en":"There is an old TV inside the house.","romaji":"Ie no naka ni furui terebi ga arimasu."}],"example":"教室に机があります。","exampleMeaning":"There is a desk in the classroom."},{"pattern":"～いかがですか。 (〜ikaga desu ka.)","meaning":"A polite way to ask someone's thoughts, opinions, or preferences; 'how about', 'how is'.","formation":"Noun + は + いかがですか / (Verb-て form + は) いかがですか","examples":[{"jp":"お茶はいかがですか？","en":"How about some tea?","romaji":"Ocha wa ikaga desu ka?"},{"jp":"このドレスはいかがですか？","en":"How about this dress?","romaji":"Kono doresu wa ikaga desu ka?"},{"jp":"ケーキを食べてはいかがですか？","en":"How about eating some cake?","romaji":"Keeki wo tabete wa ikaga desu ka?"},{"jp":"映画を見てはいかがですか？","en":"How about watching a movie?","romaji":"Eiga wo mite wa ikaga desu ka?"}],"example":"お茶はいかがですか？","exampleMeaning":"How about some tea?"},{"pattern":"いくつ～","meaning":"Used to express 'how many' or ask for the number of something.","formation":"いくつ + Noun (optional)","examples":[{"jp":"リンゴはいくつありますか？","en":"How many apples are there?","romaji":"Ringo wa ikutsu arimasu ka?"},{"jp":"いくつかの問題を解決しなければなりません。","en":"I have to solve several problems.","romaji":"Ikutsu ka no mondai o kaiketsu shinakereba narimasen."},{"jp":"あなたはいくつの言語を話せますか？","en":"How many languages can you speak?","romaji":"Anata wa ikutsu no gengo o hanasemasu ka?"},{"jp":"パーティーにはいくつかの飲み物があります。","en":"There are several drinks at the party.","romaji":"Paatii ni wa ikutsu ka no nomimono ga arimasu."}],"example":"リンゴはいくつありますか？","exampleMeaning":"How many apples are there?"},{"pattern":"いつか～","meaning":"Indicates an unspecified point in time; 'someday', 'one day', 'at some point'.","formation":"いつか + sentence","examples":[{"jp":"いつか日本に行きたいです。","en":"I want to go to Japan someday.","romaji":"Itsuka Nihon ni ikitai desu."},{"jp":"彼はいつか有名な作家になるでしょう。","en":"He will become a famous writer someday.","romaji":"Kare wa itsuka yuumei na sakka ni naru deshou."},{"jp":"いつかあの山を登りたいと思っています。","en":"I think I want to climb that mountain someday.","romaji":"Itsuka ano yama wo noboritai to omotte imasu."},{"jp":"彼女はいつか夢を叶えることができると信じています。","en":"I believe she can achieve her dream someday.","romaji":"Kanojo wa itsuka yume wo kanaeru koto ga dekiru to shinjiteimasu."}],"example":"いつか日本に行きたいです。","exampleMeaning":"I want to go to Japan someday."},{"pattern":"いつでも～","meaning":"Expresses 'anytime', 'always', or 'whenever'.","formation":"いつでも + (Verb)","examples":[{"jp":"いつでも遊びに来てください。","en":"Please come to play anytime.","romaji":"Itsudemo asobi ni kite kudasai."},{"jp":"彼女はいつでも笑顔です。","en":"She is always smiling.","romaji":"Kanojo wa itsudemo egao desu."},{"jp":"いつでも電話で連絡できます。","en":"You can contact me by phone anytime.","romaji":"Itsudemo denwa de renraku dekimasu."},{"jp":"この店はいつでも混んでいます。","en":"This store is always crowded.","romaji":"Kono mise wa itsudemo konde imasu."}],"example":"いつでも遊びに来てください。","exampleMeaning":"Please come to play anytime."},{"pattern":"いつも～","meaning":"Expressing 'always' or 'usually' in a sentence.","formation":"いつも + Verb / Adjective / Noun","examples":[{"jp":"彼はいつも遅刻します。","en":"He is always late.","romaji":"Kare wa itsumo chikoku shimasu."},{"jp":"私はいつも優しい犬が好きです。","en":"I always like gentle dogs.","romaji":"Watashi wa itsumo yasashii inu ga suki desu."},{"jp":"彼女はいつも静かな場所で勉強します。","en":"She always studies in a quiet place.","romaji":"Kanojo wa itsumo shizuka na basho de benkyou shimasu."},{"jp":"いつも朝ご飯を食べます。","en":"I always eat breakfast.","romaji":"Itsumo asagohan wo tabemasu."}],"example":"彼はいつも遅刻します。","exampleMeaning":"He is always late."},{"pattern":"～て います","meaning":"Expresses the present continuous or ongoing action; 'to be doing', 'currently doing'.","formation":"Verb て-form + います","examples":[{"jp":"今、音楽を聞いています。","en":"I am listening to music right now.","romaji":"Ima, ongaku wo kiite imasu."},{"jp":"父は新聞を読んでいます。","en":"My father is reading a newspaper.","romaji":"Chichi wa shinbun wo yonde imasu."},{"jp":"彼女は英語を勉強しています。","en":"She is studying English.","romaji":"Kanojo wa eigo wo benkyou shite imasu."},{"jp":"子供たちは公園で遊んでいます。","en":"The children are playing in the park.","romaji":"Kodomotachi wa kouen de asonde imasu."}],"example":"今、音楽を聞いています。","exampleMeaning":"I am listening to music right now."},{"pattern":"～が (〜ga)","meaning":"Particle indicating the subject of a sentence or expressing 'but'.","formation":"Noun + が / い-Adjective + が / な-Adjective + が / Verb + が","examples":[{"jp":"私が学生です。","en":"I am a student.","romaji":"Watashi ga gakusei desu."},{"jp":"このりんごが美味しい。","en":"This apple is delicious.","romaji":"Kono ringo ga oishii."},{"jp":"彼は頭がいいが、性格が悪い。","en":"He is smart but has a bad personality.","romaji":"Kare wa atama ga ii ga, seikaku ga warui."},{"jp":"走りたいが、足が痛い。","en":"I want to run, but my leg hurts.","romaji":"Hashiritai ga, ashi ga itai."}],"example":"私が学生です。","exampleMeaning":"I am a student."},{"pattern":"～が、～ (〜ga, 〜)","meaning":"Express a contrast between two sentences; 'but', 'however'.","formation":"Sentence 1 + が、+ Sentence 2","examples":[{"jp":"デザートは美味しいが、カロリーが高い。","en":"The dessert is delicious, but it is high in calories.","romaji":"Dezaato wa oishii ga, karorii ga takai."},{"jp":"彼は頭がいいが、少し怠け者だ。","en":"He is smart, but a bit lazy.","romaji":"Kare wa atama ga ii ga, sukoshi namakemono da."},{"jp":"会社は利益を上げたが、従業員の給与は上がらなかった。","en":"The company made a profit, however, the employees' salaries did not increase.","romaji":"Kaisha wa rieki wo ageta ga, juugyouin no kyuuyo wa agaranakatta."},{"jp":"外国語を勉強することが楽しいが、時々難しい。","en":"Studying foreign languages is fun, but sometimes difficult.","romaji":"Gaikokugo wo benkyou suru koto ga tanoshii ga, tokidoki muzukashii."}],"example":"デザートは美味しいが、カロリーが高い。","exampleMeaning":"The dessert is delicious, but it is high in calories."},{"pattern":"～から、～ (〜kara、～)","meaning":"Expresses reason or cause; 'because', 'since', 'so'.","formation":"Verb-casual + から / い-Adjective + から / な-Adjective + だから / Noun + だから","examples":[{"jp":"明日は試験があるから、今晩勉強しなければなりません。","en":"Because I have an exam tomorrow, I must study tonight.","romaji":"Ashita wa shiken ga aru kara, konban benkyou shinakereba narimasen."},{"jp":"この部屋は狭いから、もっと大きい部屋を探しています。","en":"Since this room is small, I am looking for a bigger one.","romaji":"Kono heya wa semai kara, motto ookii heya wo sagashiteimasu."},{"jp":"彼は友達だから、手伝ってくれるでしょう。","en":"Since he is my friend, he will probably help me.","romaji":"Kare wa tomodachi dakara, tetsudatte kureru deshou."},{"jp":"雨が降ったから、外に出られません。","en":"Because it rained, I can't go outside.","romaji":"Ame ga futta kara, soto ni deraremasen."}],"example":"明日は試験があるから、今晩勉強しなければなりません。","exampleMeaning":"Because I have an exam tomorrow, I must study tonight."},{"pattern":"～からです (〜kara desu)","meaning":"Express the reason or cause; 'because', 'since', 'due to'.","formation":"Verb-casual + からです / い-Adjective + からです / な-Adjective + だからです / Noun + だからです","examples":[{"jp":"寒いからです。コートを着ています。","en":"It’s because it’s cold. That’s why I’m wearing a coat.","romaji":"Samui kara desu. Kooto wo kiteimasu."},{"jp":"この店は安いからです。よく来ます。","en":"It’s because this store is cheap. That’s why I come often.","romaji":"Kono mise wa yasui kara desu. Yoku kimasu."},{"jp":"彼は親切だからです。みんなに好かれています。","en":"It’s because he’s kind. Everyone likes him.","romaji":"Kare wa shinsetsu dakara desu. Minna ni suka-rete imasu."},{"jp":"彼女は学生だからです。図書館で勉強しています。","en":"It’s because she’s a student. She studies at the library.","romaji":"Kanojo wa gakusei dakara desu. Toshokan de benkyou shiteimasu."}],"example":"寒いからです。コートを着ています。","exampleMeaning":"It’s because it’s cold. That’s why I’m wearing a coat."},{"pattern":"～から もらいます (〜kara moraimasu)","meaning":"To receive something or get someone to do something.","formation":"Noun + から + (Verb-て form) + もらいます","examples":[{"jp":"友達からプレゼントをもらいました。","en":"I received a present from my friend.","romaji":"Tomodachi kara purezento wo moraimashita."},{"jp":"先生に宿題を渡してもらいました。","en":"I had the teacher hand me the homework.","romaji":"Sensei ni shukudai wo watashite moraimashita."},{"jp":"お母さんに料理を作ってもらいました。","en":"I got my mom to cook for me.","romaji":"Okaasan ni ryouri wo tsukutte moraimashita."},{"jp":"兄に車を貸してもらいました。","en":"I got my older brother to lend me his car.","romaji":"Ani ni kuruma wo kashite moraimashita."}],"example":"友達からプレゼントをもらいました。","exampleMeaning":"I received a present from my friend."},{"pattern":"～が 私に くれます (〜ga watashi ni kuremasu)","meaning":"Used to express that someone gives a gift or favor to 'me'; 'someone gives me'.","formation":"Person + が + (Thing or Action) + 私に + くれます","examples":[{"jp":"彼がプレゼントを私にくれました。","en":"He gave me a present.","romaji":"Kare ga purezento wo watashi ni kuremashita."},{"jp":"友達が宿題を手伝って私にくれました。","en":"My friend helped me with my homework.","romaji":"Tomodachi ga shukudai wo tetsudatte watashi ni kuremashita."},{"jp":"お母さんがお弁当を作って私にくれました。","en":"My mom made me a lunch box.","romaji":"Okaasan ga obentou wo tsukutte watashi ni kuremashita."},{"jp":"先生がアドバイスを私にくれました。","en":"The teacher gave me advice.","romaji":"Sensei ga adobaisu wo watashi ni kuremashita."}],"example":"彼がプレゼントを私にくれました。","exampleMeaning":"He gave me a present."},{"pattern":"～けど、～ (〜kedo、～)","meaning":"Used to connect two clauses; 'but', 'however', 'although'","formation":"Verb-casual + けど / い-adjective + けど / な-adjective + だけど / Noun + だけど","examples":[{"jp":"授業に出たけど、まだ宿題をしないといけない。","en":"I attended the class, but I still have to do my homework.","romaji":"Jugyou ni deta kedo, mada shukudai wo shinai to ikenai."},{"jp":"昨日寒かったけど、今日は暖かいです。","en":"Yesterday was cold, but today is warm.","romaji":"Kinou samukatta kedo, kyou wa atatakai desu."},{"jp":"彼は親切だけど、ちょっと怖い。","en":"He is kind, but a little scary.","romaji":"Kare wa shinsetsu da kedo, chotto kowai."},{"jp":"これはおいしそうだけど、高すぎる。","en":"This looks delicious, but it is too expensive.","romaji":"Kore wa oishisou da kedo, takasugiru."}],"example":"授業に出たけど、まだ宿題をしないといけない。","exampleMeaning":"I attended the class, but I still have to do my homework."},{"pattern":"～けれど、～ (〜keredo、～)","meaning":"Expresses a contrast or contradiction; 'but', 'however', 'even though'.","formation":"Verb-casual + けれど / い-Adjective + けれど / な-Adjective + だけれど / Noun + だけれど","examples":[{"jp":"今日は寒いけれど、散歩に行きます。","en":"Even though it's cold today, I'll go for a walk.","romaji":"Kyou wa samui keredo, sanpo ni ikimasu."},{"jp":"彼は親切けれど、少し怖いです。","en":"He is kind, but a little scary.","romaji":"Kare wa shinsetsu keredo, sukoshi kowai desu."},{"jp":"この部屋は狭いけれど、明るいです。","en":"This room is small, but it's bright.","romaji":"Kono heya wa semai keredo, akarui desu."},{"jp":"彼女は病気だけれど、毎日働いています。","en":"She is sick, but she works every day.","romaji":"Kanojo wa byouki dakeredo, mainichi hataraite imasu."}],"example":"今日は寒いけれど、散歩に行きます。","exampleMeaning":"Even though it's cold today, I'll go for a walk."},{"pattern":"こちら～","meaning":"Refers to a person, place or thing; 'this', 'this one', 'this way', 'here'.","formation":"こちら / こちら + の + Person/Thing","examples":[{"jp":"こちらは田中さんです。","en":"This is Mr./Ms. Tanaka.","romaji":"Kochira wa Tanaka-san desu."},{"jp":"こちらのレストランは美味しいです。","en":"This restaurant is delicious.","romaji":"Kochira no resutoran wa oishii desu."},{"jp":"こちらへどうぞ。","en":"Please come this way.","romaji":"Kochira e douzo."},{"jp":"こちらの方がいいですか、それともあちらの方がいいですか？","en":"Is this one better, or is that one better?","romaji":"Kochira no hou ga ii desu ka, sore to mo achira no hou ga ii desu ka?"}],"example":"こちらは田中さんです。","exampleMeaning":"This is Mr./Ms. Tanaka."},{"pattern":"さっき～","meaning":"Refers to a short time ago or just now.","formation":"さっき + verb / さっき + phrase","examples":[{"jp":"さっき電話がありました。","en":"There was a phone call just now.","romaji":"Sakki denwa ga arimashita."},{"jp":"さっき部屋を掃除しました。","en":"I cleaned the room a short while ago.","romaji":"Sakki heya wo souji shimashita."},{"jp":"さっき彼に会いました。","en":"I met him just now.","romaji":"Sakki kare ni aimashita."},{"jp":"さっきのニュースを見ましたか？","en":"Did you watch the news a short time ago?","romaji":"Sakki no nyuusu wo mimashita ka?"}],"example":"さっき電話がありました。","exampleMeaning":"There was a phone call just now."},{"pattern":"すぐに～","meaning":"Immediately or right away; used to express promptness or quickness.","formation":"すぐに + Verb/Adjective","examples":[{"jp":"友達が来たら、すぐに電話をかけてください。","en":"When my friend arrives, please call me right away.","romaji":"Tomodachi ga kitara, sugu ni denwa wo kakete kudasai."},{"jp":"そのニュースを聞いたら、すぐに会社に行きました。","en":"Upon hearing that news, I went to the company immediately.","romaji":"Sono nyuusu wo kiitara, sugu ni kaisha ni ikimashita."},{"jp":"彼女はすぐに泣き出した。","en":"She started crying right away.","romaji":"Kanojo wa sugu ni nakidashita."},{"jp":"教室に入ると、先生はすぐに授業を始めた。","en":"As soon as I entered the classroom, the teacher started the lesson immediately.","romaji":"Kyoushitsu ni hairu to, sensei wa sugu ni jugyou wo hajimeta."}],"example":"友達が来たら、すぐに電話をかけてください。","exampleMeaning":"When my friend arrives, please call me right away."},{"pattern":"ぜんぜん～","meaning":"Used to express 'not at all' or 'completely' in negative sentences.","formation":"ぜんぜん + [Negative verb/adjective]","examples":[{"jp":"彼はぜんぜん話さない。","en":"He doesn't talk at all.","romaji":"Kare wa zenzen hanasanai."},{"jp":"この部屋はぜんぜん暗くない。","en":"This room is not dark at all.","romaji":"Kono heya wa zenzen kurakunai."},{"jp":"彼女はぜんぜん疲れていない。","en":"She is not tired at all.","romaji":"Kanojo wa zenzen tsukarete inai."},{"jp":"その映画はぜんぜん面白くなかった。","en":"That movie was not interesting at all.","romaji":"Sono eiga wa zenzen omoshirokunakatta."}],"example":"彼はぜんぜん話さない。","exampleMeaning":"He doesn't talk at all."},{"pattern":"そして、～ (soshite、～)","meaning":"Used to connect two sentences; 'and then', 'and'.","formation":"Sentence 1 + そして + Sentence 2","examples":[{"jp":"朝起きて、そして宿題をしました。","en":"I woke up in the morning and then did my homework.","romaji":"Asa okite, soshite shukudai wo shimashita."},{"jp":"コーヒーを飲んで、そして新聞を読みました。","en":"I drank coffee and then read the newspaper.","romaji":"Koohii wo nonde, soshite shinbun wo yomimashita."},{"jp":"家を出発しました。そして、駅へ行きました。","en":"I left my house and then went to the station.","romaji":"Ie wo shuppatsu shimashita. Soshite, eki e ikimashita."},{"jp":"彼はゲームをした。そして、テレビを見ました。","en":"He played games and then watched TV.","romaji":"Kare wa geemu wo shita. Soshite, terebi wo mimashita."}],"example":"朝起きて、そして宿題をしました。","exampleMeaning":"I woke up in the morning and then did my homework."},{"pattern":"そちら～","meaning":"Indicates a direction or person in moderate distance; 'that way', 'that person'.","formation":"そちら [alone] / そちら + の + Noun","examples":[{"jp":"そちらのレストランはどうですか？","en":"How is that restaurant over there?","romaji":"Sochira no resutoran wa dou desu ka?"},{"jp":"そちらの方、お名前を教えていただけますか？","en":"Could you tell me the name of that person over there?","romaji":"Sochira no kata, onamae o oshiete itadakemasu ka?"},{"jp":"そちらに行く途中で駅があります。","en":"There is a station on the way to that direction.","romaji":"Sochira ni iku tochuu de eki ga arimasu."},{"jp":"そちらのかばん、私のと似ていますね。","en":"That bag over there looks similar to mine.","romaji":"Sochira no kaban, watashi no to niteimasu ne."}],"example":"そちらのレストランはどうですか？","exampleMeaning":"How is that restaurant over there?"},{"pattern":"それから、～ (sorekara、～)","meaning":"Meaning 'after that', 'and then' or 'then', indicating sequence of events.","formation":"Clause 1 + それから + Clause 2","examples":[{"jp":"コーヒーを飲んで、それから家を出ました。","en":"I drank coffee, and then I left the house.","romaji":"Koohii o nonde, sorekara ie o demashita."},{"jp":"買い物をして、それから映画を見に行きました。","en":"I went shopping, and then I went to watch a movie.","romaji":"Kaimono o shite, sorekara eiga o mini ikimashita."},{"jp":"彼女は勉強をして、それから寝ました。","en":"She studied, and then she went to sleep.","romaji":"Kanojo wa benkyou o shite, sorekara nemashita."},{"jp":"パーティーに行って、それから友達と話しました。","en":"I went to the party, and then I talked with my friends.","romaji":"Paatii ni itte, sorekara tomodachi to hanashimashita."}],"example":"コーヒーを飲んで、それから家を出ました。","exampleMeaning":"I drank coffee, and then I left the house."},{"pattern":"だいたい〜 (daitai〜)","meaning":"Expresses 'roughly', 'approximately', or 'almost'.","formation":"だいたい + Number/Amount/Percentage","examples":[{"jp":"だいたい１００人がパーティーに参加しました。","en":"Approximately 100 people attended the party.","romaji":"Daitai hyaku-nin ga paatii ni sanka shimashita."},{"jp":"彼女はだいたい２時間でその仕事を終えます。","en":"She finishes that work in roughly two hours.","romaji":"Kanojo wa daitai ni-jikan de sono shigoto o oemasu."},{"jp":"だいたい８０％の生徒が試験に合格しました。","en":"About 80% of the students passed the exam.","romaji":"Daitai hachijuu-paasento no seito ga shiken ni goukaku shimashita."},{"jp":"今日はだいたい３０度の暑さです。","en":"Today is almost 30 degrees hot.","romaji":"Kyou wa daitai sanjuu-do no atsusa desu."}],"example":"だいたい１００人がパーティーに参加しました。","exampleMeaning":"Approximately 100 people attended the party."},{"pattern":"たいてい～","meaning":"Used for expressing 'usually', 'mostly', or 'generally'.","formation":"たいてい + Verb/い-Adjective/な-Adjective/Noun","examples":[{"jp":"たいてい朝８時に起きます。","en":"I usually wake up at 8 o'clock in the morning.","romaji":"Taitei asa hachi-ji ni okimasu."},{"jp":"彼はたいてい遅刻します。","en":"He is usually late.","romaji":"Kare wa taitei chikoku shimasu."},{"jp":"この店の商品はたいてい安いです。","en":"The items at this store are usually cheap.","romaji":"Kono mise no shouhin wa taitei yasui desu."},{"jp":"たいていの人はその映画が好きです。","en":"Most people like that movie.","romaji":"Taitei no hito wa sono eiga ga suki desu."}],"example":"たいてい朝８時に起きます。","exampleMeaning":"I usually wake up at 8 o'clock in the morning."},{"pattern":"だから、～ (dakara、～)","meaning":"Expresses a reason or cause; 'because', 'so', 'therefore'.","formation":"Noun + だから / な-Adjective + だから","examples":[{"jp":"雨だから、傘を持って行きましょう。","en":"Because it's raining, let's bring an umbrella.","romaji":"Ame dakara, kasa wo motte ikimashou."},{"jp":"このケーキは有名だから、みんなが食べたいです。","en":"Because this cake is famous, everyone wants to eat it.","romaji":"Kono keeki wa yuumei dakara, minna ga tabetai desu."},{"jp":"彼は病気だから、学校に行けません。","en":"Because he is sick, he cannot go to school.","romaji":"Kare wa byouki dakara, gakkou ni ikemasen."},{"jp":"彼女は学生だから、このレストランで割引があります。","en":"Because she is a student, there is a discount at this restaurant.","romaji":"Kanojo wa gakusei dakara, kono resutoran de waribiki ga arimasu."}],"example":"雨だから、傘を持って行きましょう。","exampleMeaning":"Because it's raining, let's bring an umbrella."},{"pattern":"～たり、～たり します (〜tari, 〜tari shimasu)","meaning":"Used to list multiple actions or states; 'do things like', 'and'.","formation":"Verb-casual-past + たり + Verb-casual-past + たり + します","examples":[{"jp":"休日には、映画を見たり、友達と遊んだりします。","en":"On holidays, I do things like watch movies and hang out with friends.","romaji":"Kyuujitsu ni wa, eiga wo mitari, tomodachi to asondari shimasu."},{"jp":"彼は歌ったり、踊ったり、ピアノを弾いたりします。","en":"He sings, dances, plays the piano, among other things.","romaji":"Kare wa utattari, odottari, piano wo hikitari shimasu."},{"jp":"このレストランでは、寿司を食べたり、刺身を食べたりします。","en":"At this restaurant, you can eat sushi, sashimi, and so on.","romaji":"Kono resutoran de wa, sushi wo tabetari, sashimi wo tabetari shimasu."},{"jp":"彼女は毎朝、ジョギングしたり、ヨガをしたりします。","en":"Every morning, she does things like jogging and yoga.","romaji":"Kanojo wa maiasa, joggingu shitari, yoga wo shitari shimasu."}],"example":"休日には、映画を見たり、友達と遊んだりします。","exampleMeaning":"On holidays, I do things like watch movies and hang out with friends."},{"pattern":"だれ～","meaning":"Asking 'who' in a sentence, used to inquire about someone's identity or to clarify who is being referred to.","formation":"だれ + appropriate particle (が, は or を)","examples":[{"jp":"だれがその本を買いましたか。","en":"Who bought that book?","romaji":"Dare ga sono hon o kaimashita ka."},{"jp":"だれを待っていますか。","en":"Whom are you waiting for?","romaji":"Dare o matteimasu ka."},{"jp":"だれがそのリンゴを食べましたか。","en":"Who ate that apple?","romaji":"Dare ga sono ringo o tabemashita ka."},{"jp":"だれが鍵を持っていますか。","en":"Who has the key?","romaji":"Dare ga kagi o motteimasu ka."}],"example":"だれがその本を買いましたか。","exampleMeaning":"Who bought that book?"},{"pattern":"だれか〜 (dareka〜)","meaning":"Indicates 'someone' or something done or possessed by 'someone'.","formation":"だれか + Verb, だれか + Adjective, だれか + Noun","examples":[{"jp":"だれかがドアをノックしました。","en":"Someone knocked on the door.","romaji":"Dareka ga doa wo nokku shimashita."},{"jp":"だれかが私の傘を盗みました。","en":"Someone stole my umbrella.","romaji":"Dareka ga watashi no kasa wo nusumimashita."},{"jp":"だれか助けてください。","en":"Someone, please help.","romaji":"Dareka tasukete kudasai."},{"jp":"だれかのせいで、電気がきれました。","en":"Because of someone, the electricity went out.","romaji":"Dareka no sei de, denki ga kiremashita."}],"example":"だれかがドアをノックしました。","exampleMeaning":"Someone knocked on the door."},{"pattern":"だれでも～","meaning":"Used to express 'anyone' or 'everyone'; 'no matter who'.","formation":"だれでも + Verb/Adjective/Noun","examples":[{"jp":"だれでもこのゲームができます。","en":"Anyone can play this game.","romaji":"Dare demo kono geemu ga dekimasu."},{"jp":"だれでも疲れることがあります。","en":"Everyone gets tired sometimes.","romaji":"Dare demo tsukareru koto ga arimasu."},{"jp":"だれでも無料でこのイベントに参加できます。","en":"Anyone can participate in this event for free.","romaji":"Dare demo muryou de kono ibento ni sanka dekimasu."},{"jp":"だれでもこの町の観光スポットを楽しむことができます。","en":"No matter who you are, you can enjoy the sightseeing spots in this town.","romaji":"Dare demo kono machi no kankou supotto wo tanoshimu koto ga dekimasu."}],"example":"だれでもこのゲームができます。","exampleMeaning":"Anyone can play this game."},{"pattern":"だれも～ないです","meaning":"Express 'nobody' or 'no one' in a negative sentence.","formation":"だれも + Verb-negative form (ないです), だれも + い-Adjective-negative form (ないです), だれも + な-Adjective-negative form (じゃないです)","examples":[{"jp":"だれも知らないです。","en":"Nobody knows.","romaji":"Daremo shiranai desu."},{"jp":"だれも来ないです。","en":"Nobody is coming.","romaji":"Daremo konai desu."},{"jp":"彼女はだれも好きじゃないです。","en":"She doesn't like anyone.","romaji":"Kanojo wa daremo suki ja nai desu."},{"jp":"ここにはだれもいないです。","en":"There is nobody here.","romaji":"Koko ni wa daremo inai desu."}],"example":"だれも知らないです。","exampleMeaning":"Nobody knows."},{"pattern":"だれも～ません","meaning":"Express 'nobody' or 'no one' in negative sentences.","formation":"だれも + Verb-negative (ません)","examples":[{"jp":"だれも秘密を知りません。","en":"No one knows the secret.","romaji":"Daremo himitsu wo shirimasen."},{"jp":"だれもその質問に答えませんでした。","en":"Nobody answered that question.","romaji":"Daremo sono shitsumon ni kotaemasen deshita."},{"jp":"だれも彼を助けてあげません。","en":"Nobody will help him.","romaji":"Daremo kare wo tasukete agemasen."},{"jp":"だれもその映画を見たがりません。","en":"No one wants to watch that movie.","romaji":"Daremo sono eiga wo mitagarimasen."}],"example":"だれも秘密を知りません。","exampleMeaning":"No one knows the secret."},{"pattern":"～どう しますか。 (～dou shimasu ka.)","meaning":"Asking for someone's opinion or decision; 'what will you do?', 'how will you handle it?'.","formation":"Situation + どうしますか","examples":[{"jp":"雨が降っているので、どうしますか？","en":"It's raining, so what will you do?","romaji":"Ame ga futte iru node, dou shimasu ka?"},{"jp":"この問題について、どうしますか？","en":"What are you going to do about this issue?","romaji":"Kono mondai ni tsuite, dou shimasu ka?"},{"jp":"彼が来なかったら、どうしますか？","en":"If he doesn't come, what will you do?","romaji":"Kare ga konakattara, dou shimasu ka?"},{"jp":"進路を決める時、どうしますか？","en":"What will you do when choosing your career path?","romaji":"Shinro wo kimeru toki, dou shimasu ka?"}],"example":"雨が降っているので、どうしますか？","exampleMeaning":"It's raining, so what will you do?"},{"pattern":"～どうですか。 (〜dou desu ka.)","meaning":"Asking for opinions or suggestions; 'how about', 'what do you think of'.","formation":"Noun + は/が + どうですか / Verb-casual + の + どうですか / い-Adjective + どうですか / な-Adjective + な + どうですか","examples":[{"jp":"この映画はどうですか？","en":"How about this movie? / What do you think of this movie?","romaji":"Kono eiga wa dou desu ka?"},{"jp":"晩ご飯に寿司を食べるのはどうですか？","en":"How about eating sushi for dinner?","romaji":"Bangohan ni sushi wo taberu no wa dou desu ka?"},{"jp":"この部屋は広いと思いますが、どうですか？","en":"I think this room is spacious, what do you think?","romaji":"Kono heya wa hiroi to omoimasu ga, dou desu ka?"},{"jp":"新しい会社の要件が厳しいですね。鈴木さん、転職するならどうですか？","en":"The new company's requirements are strict, aren't they? Suzuki-san, how about changing jobs if that's the case?","romaji":"Atarashii kaisha no youken ga kibishii desu ne. Suzuki-san, tenshoku suru nara dou desu ka?"}],"example":"この映画はどうですか？","exampleMeaning":"How about this movie? / What do you think of this movie?"},{"pattern":"どうやって～","meaning":"Ask 'how' something is done or how to do something.","formation":"どうやって + Verb-casual","examples":[{"jp":"どうやってお寿司を作りますか？","en":"How do you make sushi?","romaji":"Douyatte o-sushi wo tsukurimasu ka?"},{"jp":"どうやって日本語を勉強しましたか？","en":"How did you study Japanese?","romaji":"Douyatte nihongo wo benkyou shimashita ka?"},{"jp":"どうやってこの問題を解決しますか？","en":"How do you solve this problem?","romaji":"Douyatte kono mondai wo kaiketsu shimasu ka?"},{"jp":"どうやって駅に行きますか？","en":"How do you go to the station?","romaji":"Douyatte eki ni ikimasu ka?"}],"example":"どうやってお寿司を作りますか？","exampleMeaning":"How do you make sushi?"},{"pattern":"～どう 言いますか。 (〜dou iimasu ka.)","meaning":"Asking for the way to say something; 'how do you say'.","formation":"Word/Phrase + は [language]でどう言いますか / Word/Phrase + をどう言いますか","examples":[{"jp":"「ありがとう」は英語でどう言いますか。","en":"How do you say 'thank you' in English?","romaji":"「Arigatou」wa eigo de dou iimasu ka."},{"jp":"この言葉を日本語でどう言いますか。","en":"How do you say this word in Japanese?","romaji":"Kono kotoba wo nihongo de dou iimasu ka."},{"jp":"「すみません」はフランス語でどう言いますか。","en":"How do you say 'excuse me' in French?","romaji":"「Sumimasen」wa furansugo de dou iimasu ka."},{"jp":"その表現をスペイン語でどう言いますか。","en":"How do you say that expression in Spanish?","romaji":"Sono hyougen wo supeingo de dou iimasu ka."}],"example":"「ありがとう」は英語でどう言いますか。","exampleMeaning":"How do you say 'thank you' in English?"},{"pattern":"～とき (〜toki)","meaning":"Expresses the time when something happens, 'when', 'at the time'.","formation":"Verb-casual + とき / い-Adjective + とき / な-Adjective + なとき / Noun + のとき","examples":[{"jp":"公園で遊ぶとき、帽子をかぶりましょう。","en":"When playing in the park, let's wear a hat.","romaji":"Kouen de asobu toki, boushi wo kaburimashou."},{"jp":"このりんごが赤いとき、食べごろです。","en":"This apple is ready to eat when it is red.","romaji":"Kono ringo ga akai toki, tabegoro desu."},{"jp":"私が勉強するとき、家族は静かにしてくれます。","en":"When I am studying, my family keeps quiet for me.","romaji":"Watashi ga benkyou suru toki, kazoku wa shizuka ni shite kuremasu."},{"jp":"子供のとき、よくおばあちゃんの家に遊びに行きました。","en":"When I was a child, I often went to play at my grandmother's house.","romaji":"Kodomo no toki, yoku obaachan no ie ni asobi ni ikimashita."}],"example":"公園で遊ぶとき、帽子をかぶりましょう。","exampleMeaning":"When playing in the park, let's wear a hat."},{"pattern":"ときどき～","meaning":"Used to indicate the frequency of an event; 'sometimes', 'occasionally', 'now and then'.","formation":"ときどき + Verb/Adjective/Noun","examples":[{"jp":"彼はときどきケーキを作ります。","en":"He sometimes makes cakes.","romaji":"Kare wa tokidoki keeki o tsukurimasu."},{"jp":"ときどき雨が降るので、傘を持って行ったほうがいいです。","en":"It occasionally rains, so it's better to bring an umbrella.","romaji":"Tokidoki ame ga furu node, kasa o motte itta hou ga ii desu."},{"jp":"私はときどきこの店で買い物をします。","en":"I shop at this store now and then.","romaji":"Watashi wa tokidoki kono mise de kaimono o shimasu."},{"jp":"彼女はときどき遅刻します。","en":"She is sometimes late.","romaji":"Kanojo wa tokidoki chikoku shimasu."}],"example":"彼はときどきケーキを作ります。","exampleMeaning":"He sometimes makes cakes."},{"pattern":"どこ～","meaning":"Express 'where', used with question words for asking about locations.","formation":"どこ + question particle","examples":[{"jp":"駅はどこですか？","en":"Where is the station?","romaji":"Eki wa doko desu ka?"},{"jp":"どこで映画を見ましたか？","en":"Where did you watch the movie?","romaji":"Doko de eiga wo mimashita ka?"},{"jp":"どこに住んでいますか？","en":"Where do you live?","romaji":"Doko ni sunde imasu ka?"},{"jp":"どこへ行きたいですか？","en":"Where do you want to go?","romaji":"Doko e ikitai desu ka?"}],"example":"駅はどこですか？","exampleMeaning":"Where is the station?"},{"pattern":"どこか～","meaning":"Expresses 'somewhere', used when the specific location is unknown or uncertain.","formation":"どこか + (Particle, if needed) + Verb/Noun/Adjective","examples":[{"jp":"どこかで財布をなくしました。","en":"I lost my wallet somewhere.","romaji":"Dokoka de saifu wo nakushimashita."},{"jp":"今日はどこかに行きたいです。","en":"I want to go somewhere today.","romaji":"Kyou wa dokoka ni ikitai desu."},{"jp":"どこか安いレストランがありますか？","en":"Is there a cheap restaurant somewhere?","romaji":"Dokoka yasui resutoran ga arimasu ka?"},{"jp":"どこか静かな場所で勉強したい。","en":"I want to study in a quiet place somewhere.","romaji":"Dokoka shizuka na basho de benkyou shitai."}],"example":"どこかで財布をなくしました。","exampleMeaning":"I lost my wallet somewhere."},{"pattern":"どこでも～","meaning":"Express 'anywhere' or 'everywhere' in Japanese.","formation":"Simply use the word どこでも in the sentence as an adverb to indicate 'anywhere' or 'everywhere'.","examples":[{"jp":"どこでも好きな場所で勉強できます。","en":"You can study anywhere you like.","romaji":"Dokodemo sukina basho de benkyou dekimasu."},{"jp":"このノートパソコンは便利なので、どこでもインターネットが使えます。","en":"This laptop is convenient, so you can use the internet anywhere.","romaji":"Kono nootopasokon wa benri nano de, dokodemo intaanetto ga tsukaemasu."},{"jp":"彼はどこでも寝ることができます。","en":"He can sleep anywhere.","romaji":"Kare wa dokodemo neru koto ga dekimasu."},{"jp":"彼女はどこでも歌うのが大好きです。","en":"She loves singing anywhere.","romaji":"Kanojo wa dokodemo utau no ga daisuki desu."}],"example":"どこでも好きな場所で勉強できます。","exampleMeaning":"You can study anywhere you like."},{"pattern":"どこにも + Verb + ないです (doko ni mo + Verb + nai desu)","meaning":"Express that an action cannot be performed anywhere or something cannot be found anywhere.","formation":"どこにも + Verb in ない-form + です","examples":[{"jp":"どこにも傘が売ってないです。","en":"Umbrellas are not sold anywhere.","romaji":"Doko ni mo kasa ga uttenai desu."},{"jp":"彼はどこにも見つけられないです。","en":"He cannot be found anywhere.","romaji":"Kare wa doko ni mo mitsukerarenai desu."},{"jp":"どこにも勉強できる場所がないです。","en":"There is no place to study anywhere.","romaji":"Doko ni mo benkyou dekiru basho ga nai desu."},{"jp":"どこにも美味しいビーガン料理がないです。","en":"There are no delicious vegan dishes anywhere.","romaji":"Doko ni mo oishii bi-gan ryouri ga nai desu."}],"example":"どこにも傘が売ってないです。","exampleMeaning":"Umbrellas are not sold anywhere."},{"pattern":"どこにも + Verb + ません (doko ni mo + Verb + masen)","meaning":"Express 'not anywhere' or 'nowhere' with a negative verb.","formation":"どこにも + Verb-negative","examples":[{"jp":"どこにもあの猫がいません。","en":"The cat is not anywhere.","romaji":"Doko ni mo ano neko ga imasen."},{"jp":"どこにもお金を置いていません。","en":"I didn't put the money anywhere.","romaji":"Doko ni mo okane wo oiteimasen."},{"jp":"この町にはどこにも美味しいラーメン屋がありません。","en":"There are no delicious ramen shops anywhere in this town.","romaji":"Kono machi ni wa doko ni mo oishii raamenya ga arimasen."},{"jp":"どこにも彼女の名前が書いていません。","en":"Her name is not written anywhere.","romaji":"Doko ni mo kanojo no namae ga kaiteimasen."}],"example":"どこにもあの猫がいません。","exampleMeaning":"The cat is not anywhere."},{"pattern":"どこへも Verb ないです (doko e mo + Verb + nai desu)","meaning":"Express that an action doesn't take place anywhere; 'nowhere', 'not anywhere'.","formation":"どこへも + Verb in negative form (ないです)","examples":[{"jp":"今週末どこへも行かないです。","en":"I'm not going anywhere this weekend.","romaji":"Konshuumatsu doko e mo ikanai desu."},{"jp":"彼女はどこへも買い物に行きませんでした。","en":"She didn't go shopping anywhere.","romaji":"Kanojo wa doko e mo kaimono ni ikimasen deshita."},{"jp":"スーパーはどこへも売らないです。","en":"It's not sold at any supermarket.","romaji":"Suupaa wa doko e mo uranai desu."},{"jp":"私はどこへも行く予定がないです。","en":"I have no plans to go anywhere.","romaji":"Watashi wa doko e mo iku yotei ga nai desu."}],"example":"今週末どこへも行かないです。","exampleMeaning":"I'm not going anywhere this weekend."},{"pattern":"どこへも Verb ません (doko e mo + Verb + masen)","meaning":"Nowhere; Not to any place","formation":"どこへも + Verb-negative","examples":[{"jp":"今日はどこへも行きません。","en":"I won't go anywhere today.","romaji":"Kyou wa doko e mo ikimasen."},{"jp":"彼はどこへも走りませんでした。","en":"He didn't run anywhere.","romaji":"Kare wa doko e mo hashirimasen deshita."},{"jp":"どこへも買い物に行きませんでした。","en":"I didn't go shopping anywhere.","romaji":"Doko e mo kaimono ni ikimasen deshita."},{"jp":"彼女はどこへも連れて行かせません。","en":"She won't take me anywhere.","romaji":"Kanojo wa doko e mo tsurete ikasemasen."}],"example":"今日はどこへも行きません。","exampleMeaning":"I won't go anywhere today."},{"pattern":"どこも Verb ないです (dokomo + Verb + naidesu)","meaning":"Express that something cannot be found anywhere or in any place; 'nowhere', 'in no place'.","formation":"どこも + Verb-negative","examples":[{"jp":"どこもうちわがないです。","en":"I can't find fans anywhere.","romaji":"Doko mo uchiwa ga nai desu."},{"jp":"この町ではどこも美味しいラーメンがないです。","en":"There are no delicious ramen shops anywhere in this town.","romaji":"Kono machi de wa doko mo oishii raamen ga nai desu."},{"jp":"どこも駐車場がないです。","en":"There is no parking anywhere.","romaji":"Doko mo chuushajou ga nai desu."},{"jp":"どこも席がないです。","en":"There are no seats available anywhere.","romaji":"Doko mo seki ga nai desu."}],"example":"どこもうちわがないです。","exampleMeaning":"I can't find fans anywhere."},{"pattern":"どこも Verb ません (dokomo + Verb + masen)","meaning":"Express that 'nowhere' meets the verb action; 'nowhere does/can'.","formation":"どこも + Verb-ます form + ません","examples":[{"jp":"どこも静かじゃありません。","en":"Nowhere is quiet.","romaji":"Doko mo shizuka ja arimasen."},{"jp":"どこもその本を売っていません。","en":"Nowhere sells that book.","romaji":"Doko mo sono hon wo utte imasen."},{"jp":"この地域では、どこもインターネットに接続できません。","en":"In this area, nowhere can connect to the internet.","romaji":"Kono chiiki de wa, doko mo intaanetto ni setsuzoku dekimasen."},{"jp":"どこも彼を知りません。","en":"No place knows him.","romaji":"Doko mo kare wo shirimasen."}],"example":"どこも静かじゃありません。","exampleMeaning":"Nowhere is quiet."},{"pattern":"どちら～","meaning":"Used to ask about two choices or options.","formation":"どちら + が/を + verb, どちら + が/を + adjective, どちら + が/を + noun","examples":[{"jp":"この二つのリンゴ、どちらが美味しいですか？","en":"Which of these two apples is delicious?","romaji":"Kono futatsu no ringo, dochira ga oishii desu ka?"},{"jp":"どちらのドレスを着たいですか？","en":"Which dress would you like to wear?","romaji":"Dochira no doresu wo kitai desu ka?"},{"jp":"この二つの町、どちらに行きたいですか？","en":"Which of these two towns do you want to go to?","romaji":"Kono futatsu no machi, dochira ni ikitai desu ka?"},{"jp":"どちらの映画が面白いと思いますか？","en":"Which movie do you think is interesting?","romaji":"Dochira no eiga ga omoshiroi to omoimasu ka?"}],"example":"この二つのリンゴ、どちらが美味しいですか？","exampleMeaning":"Which of these two apples is delicious?"},{"pattern":"どなた～","meaning":"A polite way to ask 'who', used for asking about someone's identity or when seeking information about an unknown person.","formation":"どなた","examples":[{"jp":"すみません、どなたが山田さんですか？","en":"Excuse me, who is Mr. Yamada?","romaji":"Sumimasen, donata ga Yamada-san desu ka?"},{"jp":"どなたも知っている有名な俳優です。","en":"He is a famous actor whom everyone knows.","romaji":"Donata mo shitte iru yuumei na haiyuu desu."},{"jp":"明日のパーティーにはどなたが来ますか？","en":"Who is coming to the party tomorrow?","romaji":"Ashita no paatii ni wa donata ga kimasu ka?"},{"jp":"どなたか手伝っていただけますか？","en":"Could someone please help me?","romaji":"Donata ka tetsudatte itadakemasu ka?"}],"example":"すみません、どなたが山田さんですか？","exampleMeaning":"Excuse me, who is Mr. Yamada?"},{"pattern":"どの Noun","meaning":"Expresses 'which'; used to ask about specific items within a group.","formation":"どの + Noun","examples":[{"jp":"どの本が一番面白いですか。","en":"Which book is the most interesting?","romaji":"Dono hon ga ichiban omoshiroi desu ka?"},{"jp":"どの服を着たいですか。","en":"Which clothes do you want to wear?","romaji":"Dono fuku wo kitai desu ka?"},{"jp":"どの色が好きですか。","en":"Which color do you like?","romaji":"Dono iro ga suki desu ka?"},{"jp":"どのレストランに行きたいですか。","en":"Which restaurant do you want to go to?","romaji":"Dono resutoran ni ikitai desu ka?"}],"example":"どの本が一番面白いですか。","exampleMeaning":"Which book is the most interesting?"},{"pattern":"どれでも～","meaning":"Indicates 'any' or 'whichever' when referring to multiple items.","formation":"どれ + でも","examples":[{"jp":"どれでもいいですか？","en":"Is any choice okay?","romaji":"Dore demo ii desu ka?"},{"jp":"どれでも選んでください。","en":"Please choose whichever you like.","romaji":"Dore demo erande kudasai."},{"jp":"どれでもおいしいです。","en":"All of them are delicious.","romaji":"Dore demo oishii desu."},{"jp":"この中でどれでも好きなものを持って行ってください。","en":"Please take whichever you like from these.","romaji":"Kono naka de dore demo suki na mono wo motte itte kudasai."}],"example":"どれでもいいですか？","exampleMeaning":"Is any choice okay?"},{"pattern":"どんな Noun","meaning":"Used to ask or describe 'what kind' or 'what type' of something.","formation":"どんな + Noun","examples":[{"jp":"どんな音楽が好きですか？","en":"What kind of music do you like?","romaji":"Donna ongaku ga suki desu ka?"},{"jp":"彼女はどんな映画が好きだと思う？","en":"What kind of movies do you think she likes?","romaji":"Kanojo wa donna eiga ga suki da to omou?"},{"jp":"どんな本が一番面白いですか？","en":"What kind of books are the most interesting?","romaji":"Donna hon ga ichiban omoshiroi desu ka?"},{"jp":"どんな料理が得意ですか？","en":"What kind of dishes are you good at making?","romaji":"Donna ryouri ga tokui desu ka?"}],"example":"どんな音楽が好きですか？","exampleMeaning":"What kind of music do you like?"},{"pattern":"なに～","meaning":"Asking about 'what' or 'which' in Japanese","formation":"Verb + なに, い-Adjective + なに, な-Adjective + なに, Noun + なに","examples":[{"jp":"これはなにですか。","en":"What is this?","romaji":"Kore wa nani desu ka?"},{"jp":"あの人はなにをしているのですか？","en":"What is that person doing?","romaji":"Ano hito wa nani wo shite iru no desu ka?"},{"jp":"なにが好きですか？","en":"What do you like?","romaji":"Nani ga suki desu ka?"},{"jp":"今日の天気はなにですか？","en":"What is today's weather?","romaji":"Kyou no tenki wa nani desu ka?"}],"example":"これはなにですか。","exampleMeaning":"What is this?"},{"pattern":"なにか～","meaning":"Indicates 'something' or 'some kind of'.","formation":"なにか + Noun","examples":[{"jp":"なにか飲み物を持ってきてください。","en":"Please bring some kind of drink.","romaji":"Nanika nomimono wo motte kite kudasai."},{"jp":"なにか質問があれば、遠慮なく聞いてください。","en":"If you have any questions, please feel free to ask.","romaji":"Nanika shitsumon ga areba, enryo naku kiite kudasai."},{"jp":"彼女はなにかプレゼントを持っている。","en":"She has some kind of present.","romaji":"Kanojo wa nanika purezento wo motte iru."},{"jp":"なにか助けが必要なら、言ってください。","en":"If you need any help, please let me know.","romaji":"Nanika tasuke ga hitsuyou nara, itte kudasai."}],"example":"なにか飲み物を持ってきてください。","exampleMeaning":"Please bring some kind of drink."},{"pattern":"なにも～ないです","meaning":"Used to express 'not any' or 'nothing' in a negative sentence.","formation":"なにも + Verb-negative","examples":[{"jp":"彼はなにも言わなかったです。","en":"He didn't say anything.","romaji":"Kare wa nani mo iwanakatta desu."},{"jp":"私はなにも食べないです。","en":"I don't eat anything.","romaji":"Watashi wa nani mo tabenai desu."},{"jp":"彼女はなにも持っていないです。","en":"She doesn't have anything.","romaji":"Kanojo wa nani mo motte inai desu."},{"jp":"この箱にはなにも入っていないです。","en":"There is nothing in this box.","romaji":"Kono hako ni wa nani mo haitte inai desu."}],"example":"彼はなにも言わなかったです。","exampleMeaning":"He didn't say anything."},{"pattern":"なにも～ません","meaning":"Used to express 'not anything', 'nothing'.","formation":"なにも + Verb-ます form + ません","examples":[{"jp":"昨日はなにも食べませんでした。","en":"I didn't eat anything yesterday.","romaji":"Kinou wa nanimo tabemasen deshita."},{"jp":"彼はなにも話しません。","en":"He doesn't say anything.","romaji":"Kare wa nanimo hanashimasen."},{"jp":"この部屋ではなにも見えません。","en":"I cannot see anything in this room.","romaji":"Kono heya de wa nanimo miemasen."},{"jp":"彼女はなにも買いませんでした。","en":"She didn't buy anything.","romaji":"Kanojo wa nanimo kaimasen deshita."}],"example":"昨日はなにも食べませんでした。","exampleMeaning":"I didn't eat anything yesterday."},{"pattern":"なん～","meaning":"Used to form interrogative questions and emphasize the question word for 'what', 'how'.","formation":"なん + Counter / なん + Verb / なん + Adjective","examples":[{"jp":"あなたはなん歳ですか？","en":"How old are you?","romaji":"Anata wa nan-sai desu ka?"},{"jp":"これはなんですか？","en":"What is this?","romaji":"Kore wa nan desu ka?"},{"jp":"彼はなんで来ましたか？","en":"Why did he come?","romaji":"Kare wa nan de kimashita ka?"},{"jp":"あのレストランはなんと言う名前ですか？","en":"What is the name of that restaurant?","romaji":"Ano resutoran wa nan to iu namae desu ka?"}],"example":"あなたはなん歳ですか？","exampleMeaning":"How old are you?"},{"pattern":"なんで～","meaning":"Asking the reason or cause; 'why', 'how come'.","formation":"なんで + [phrase or sentence]","examples":[{"jp":"なんで遅れたの？","en":"Why were you late?","romaji":"Nande okureta no?"},{"jp":"なんでこの部屋はこんなに汚いの？","en":"Why is this room so dirty?","romaji":"Nande kono heya wa konna ni kitanai no?"},{"jp":"なんで彼女は怒っているの？","en":"Why is she angry?","romaji":"Nande kanojo wa okotte iru no?"},{"jp":"なんで今日は休みなの？","en":"Why is today a holiday?","romaji":"Nande kyou wa yasumi na no?"}],"example":"なんで遅れたの？","exampleMeaning":"Why were you late?"},{"pattern":"なんでも～","meaning":"Means 'any', 'anything', 'anyone'.","formation":"なんでも + Verb / なんでも + Adjective / なんでも + Noun","examples":[{"jp":"なんでも食べられるから、何を頼んでも大丈夫です。","en":"I can eat anything, so it's okay to order whatever you want.","romaji":"Nandemo taberareru kara, nani wo tanondemo daijoubu desu."},{"jp":"なんでもよければ、この本をおすすめします。","en":"If you're okay with anything, I recommend this book.","romaji":"Nandemo yokereba, kono hon wo osusume shimasu."},{"jp":"なんでもできるスタッフを探しています。","en":"We are looking for a staff member who can do anything.","romaji":"Nandemo dekiru sutaffu wo sagashiteimasu."},{"jp":"この食堂では、なんでも美味しくて安い料理が出されます。","en":"In this cafeteria, any dish served is delicious and inexpensive.","romaji":"Kono shokudou de wa, nandemo oishikute yasui ryouri ga dasaremasu."}],"example":"なんでも食べられるから、何を頼んでも大丈夫です。","exampleMeaning":"I can eat anything, so it's okay to order whatever you want."},{"pattern":"～なんと 言いますか。 (〜nan to iimasu ka.)","meaning":"Asking how something is called or referred to; 'how do you say'","formation":"Noun + は/が + なんと言いますか","examples":[{"jp":"この花はなんと言いますか。","en":"How do you say this flower?","romaji":"Kono hana wa nan to iimasu ka."},{"jp":"この料理はなんと言いますか。","en":"What do you call this dish?","romaji":"Kono ryouri wa nan to iimasu ka."},{"jp":"日本でこれはなんと言いますか。","en":"How do you say this in Japanese?","romaji":"Nihon de kore wa nan to iimasu ka."},{"jp":"その映画の名前はなんと言いますか。","en":"What is the name of that movie?","romaji":"Sono eiga no namae wa nan to iimasu ka."}],"example":"この花はなんと言いますか。","exampleMeaning":"How do you say this flower?"},{"pattern":"～に あげます (〜 ni agemasu)","meaning":"Used to express giving something to someone; 'give', 'offer'.","formation":"Receiver + に + Object + を + あげます","examples":[{"jp":"私は友達に本をあげました。","en":"I gave a book to my friend.","romaji":"Watashi wa tomodachi ni hon wo agemashita."},{"jp":"彼にプレゼントをあげましょう。","en":"Let's give him a present.","romaji":"Kare ni purezento wo agemashou."},{"jp":"先生に花をあげます。","en":"I will give flowers to the teacher.","romaji":"Sensei ni hana wo agemasu."},{"jp":"お母さんにチョコレートをあげたいです。","en":"I want to give chocolate to my mom.","romaji":"Okaasan ni chokoreeto wo agetai desu."}],"example":"私は友達に本をあげました。","exampleMeaning":"I gave a book to my friend."},{"pattern":"～に もらいます (〜ni moraimasu)","meaning":"To receive something or some action from someone; 'to get', 'to receive'.","formation":"Giver + に + Verb-te form + もらいます / Giver + に + Object + を + もらいます","examples":[{"jp":"友達にプレゼントをもらいました。","en":"I received a gift from my friend.","romaji":"Tomodachi ni purezento wo moraimashita."},{"jp":"先生にアドバイスをもらいました。","en":"I got advice from my teacher.","romaji":"Sensei ni adobaisu wo moraimashita."},{"jp":"おばあさんに手紙を書いてもらいました。","en":"I had my grandmother write a letter for me.","romaji":"Obaasan ni tegami wo kaite moraimashita."},{"jp":"弟に宿題を手伝ってもらいました。","en":"I got help from my younger brother with my homework.","romaji":"Otouto ni shukudai wo tetsudatte moraimashita."}],"example":"友達にプレゼントをもらいました。","exampleMeaning":"I received a gift from my friend."},{"pattern":"～の (〜no)","meaning":"Express possession, apposition, or description using 'of' or ''s'.","formation":"Noun1 + の + Noun2, (Adjective/Clause) + の (nominalized), etc.","examples":[{"jp":"これは私の鞄です。","en":"This is my bag.","romaji":"Kore wa watashi no kaban desu."},{"jp":"彼女は赤いバッグを持っています。","en":"She has a red bag.","romaji":"Kanojo wa akai baggu o motte imasu."},{"jp":"彼はきれいな部屋があります。","en":"He has a clean room.","romaji":"Kare wa kirei na heya ga arimasu."},{"jp":"東京の天気は暑いです。","en":"The weather in Tokyo is hot.","romaji":"Toukyou no tenki wa atsui desu."}],"example":"これは私の鞄です。","exampleMeaning":"This is my bag."},{"pattern":"～はたいへんです (〜wa taihen desu)","meaning":"Express that something is difficult or tough.","formation":"Noun + はたいへんです","examples":[{"jp":"漢字を覚えるのはたいへんです。","en":"It is difficult to remember kanji.","romaji":"Kanji o oboeru no wa taihen desu."},{"jp":"この仕事はたいへんです。","en":"This job is tough.","romaji":"Kono shigoto wa taihen desu."},{"jp":"日本の駅のことを理解するのはたいへんです。","en":"Understanding Japanese train stations is difficult.","romaji":"Nihon no eki no koto o rikai suru no wa taihen desu."},{"jp":"彼女は病気の時、生活はたいへんです。","en":"When she is sick, life is tough.","romaji":"Kanojo wa byouki no toki, seikatsu wa taihen desu."}],"example":"漢字を覚えるのはたいへんです。","exampleMeaning":"It is difficult to remember kanji."},{"pattern":"ほとんど〜 (hotondo〜)","meaning":"Used to express 'almost', 'nearly', or 'most'.","formation":"ほとんど + Verb / ほとんど + Noun","examples":[{"jp":"彼女はほとんど英語を話せません。","en":"She can hardly speak English.","romaji":"Kanojo wa hotondo eigo o hanasemasen."},{"jp":"ほとんどの人がパーティーに出席しました。","en":"Most people attended the party.","romaji":"Hotondo no hito ga paatii ni shusseki shimashita."},{"jp":"私たちはほとんど勉強しないでテストに合格しました。","en":"We passed the test with hardly any studying.","romaji":"Watashitachi wa hotondo benkyou shinaide tesuto ni goukaku shimashita."},{"jp":"この本はほとんど読み終わりました。","en":"I have almost finished reading this book.","romaji":"Kono hon wa hotondo yomiowarimashita."}],"example":"彼女はほとんど英語を話せません。","exampleMeaning":"She can hardly speak English."},{"pattern":"まあまあ～","meaning":"Expresses something as 'so-so', 'not bad', or 'average'.","formation":"Used as an adverb or short expression with no special grammar structure.","examples":[{"jp":"彼の料理の腕前はまあまあです。","en":"His cooking skills are so-so.","romaji":"Kare no ryouri no udemae wa maa maa desu."},{"jp":"今日の天気はまあまあですね。","en":"The weather today is not bad, huh?","romaji":"Kyou no tenki wa maa maa desu ne."},{"jp":"あの映画はまあまあ面白かったです。","en":"That movie was somewhat interesting.","romaji":"Ano eiga wa maa maa omoshirokatta desu."},{"jp":"彼女の歌はまあまあ上手だと思います。","en":"I think her singing is not bad.","romaji":"Kanojo no uta wa maa maa jouzu da to omoimasu."}],"example":"彼の料理の腕前はまあまあです。","exampleMeaning":"His cooking skills are so-so."},{"pattern":"まだ〜 (mada〜)","meaning":"Indicates something has not yet happened or is still happening; 'still', 'not yet'.","formation":"まだ + Verb (non-past / negative / te-form), まだ + い-adjective, まだ + な-adjective + じゃない/ではない, まだ + Noun + じゃない/ではない","examples":[{"jp":"昼ご飯はまだ食べていません。","en":"I haven't eaten lunch yet.","romaji":"Hirugohan wa mada tabete imasen."},{"jp":"山田さんはまだ来ていません。","en":"Yamada-san has not arrived yet.","romaji":"Yamada-san wa mada kite imasen."},{"jp":"この部屋はまだ暑いです。","en":"This room is still hot.","romaji":"Kono heya wa mada atsui desu."},{"jp":"彼はまだ学生じゃないです。","en":"He is not a student yet.","romaji":"Kare wa mada gakusei ja nai desu."}],"example":"昼ご飯はまだ食べていません。","exampleMeaning":"I haven't eaten lunch yet."},{"pattern":"まだ〜ないです (mada 〜 nai desu)","meaning":"Expresses that something has not happened or been done yet.","formation":"まだ + Verb-negative + です","examples":[{"jp":"まだ宿題をしていないです。","en":"I haven't done my homework yet.","romaji":"Mada shukudai o shite inai desu."},{"jp":"彼はまだ来ないです。","en":"He hasn't come yet.","romaji":"Kare wa mada konai desu."},{"jp":"映画はまだ始まっていないです。","en":"The movie hasn't started yet.","romaji":"Eiga wa mada hajimatte inai desu."},{"jp":"私たちはまだ夕食を食べていないです。","en":"We haven't eaten dinner yet.","romaji":"Watashitachi wa mada yuushoku o tabete inai desu."}],"example":"まだ宿題をしていないです。","exampleMeaning":"I haven't done my homework yet."},{"pattern":"まだ～ません","meaning":"Expresses that something has not happened or been done yet (polite form).","formation":"まだ + Verb-ます form (negative)","examples":[{"jp":"昼ご飯をまだ食べていません。","en":"I have not eaten lunch yet.","romaji":"Hirugohan o mada tabete imasen."},{"jp":"宿題がまだ終わっていません。","en":"I have not finished my homework yet.","romaji":"Shukudai ga mada owatte imasen."},{"jp":"東京にはまだ行ったことがありません。","en":"I have not been to Tokyo yet.","romaji":"Toukyou ni wa mada itta koto ga arimasen."},{"jp":"彼はまだ来ていません。","en":"He hasn't come yet.","romaji":"Kare wa mada kite imasen."}],"example":"昼ご飯をまだ食べていません。","exampleMeaning":"I have not eaten lunch yet."},{"pattern":"もう～","meaning":"Expresses 'already', 'anymore', or 'soon'.","formation":"もう + Verb / もう + Adjective / もう + Noun","examples":[{"jp":"もう昼ごはんを食べました。","en":"I already ate lunch.","romaji":"Mou hirugohan o tabemashita."},{"jp":"もうここでは働かない。","en":"I won't work here anymore.","romaji":"Mou koko de wa hatarakanai."},{"jp":"もうすぐ夏休みですね。","en":"Summer vacation is coming soon, isn't it?","romaji":"Mou sugu natsuyasumi desu ne."},{"jp":"もう十分です。","en":"It's already enough.","romaji":"Mou juubun desu."}],"example":"もう昼ごはんを食べました。","exampleMeaning":"I already ate lunch."},{"pattern":"もうすぐ〜","meaning":"Express an action or event happening soon: 'soon', 'in a short while', 'almost'.","formation":"もうすぐ + Verb (~ます form or 〜る form)","examples":[{"jp":"もうすぐ春が来ます。","en":"Spring is coming soon.","romaji":"Mou sugu haru ga kimasu."},{"jp":"もうすぐ彼女の誕生日です。","en":"Her birthday is coming up soon.","romaji":"Mou sugu kanojo no tanjoubi desu."},{"jp":"もうすぐ試験が終わる。","en":"The exam will be over soon.","romaji":"Mou sugu shiken ga owaru."},{"jp":"もうすぐ雨が止むでしょう。","en":"The rain will likely stop soon.","romaji":"Mou sugu ame ga yamu deshou."}],"example":"もうすぐ春が来ます。","exampleMeaning":"Spring is coming soon."},{"pattern":"もっと〜 (motto〜)","meaning":"Expresses 'more' or 'even more' when describing a quantity, frequency, or degree.","formation":"もっと + Verb / い-Adjective / な-Adjective","examples":[{"jp":"もっと勉強しなければなりません。","en":"I have to study more.","romaji":"Motto benkyou shinakereba narimasen."},{"jp":"このかばんをもっと大きいサイズに変えたいです。","en":"I want to change this bag to a larger size.","romaji":"Kono kaban o motto ookii saizu ni kaetai desu."},{"jp":"もっと静かな場所で働きたいです。","en":"I want to work in a quieter place.","romaji":"Motto shizuka na basho de hatarakitai desu."},{"jp":"彼女はもっと上手になりたいと思っています。","en":"She wants to become even better.","romaji":"Kanojo wa motto jouzu ni naritai to omotte imasu."}],"example":"もっと勉強しなければなりません。","exampleMeaning":"I have to study more."},{"pattern":"よく～","meaning":"Often used to express 'doing something well' or 'often'.","formation":"よく + Verb-casual","examples":[{"jp":"彼はよく勉強します。","en":"He studies often.","romaji":"Kare wa yoku benkyou shimasu."},{"jp":"彼女はよく料理を作ります。","en":"She often cooks.","romaji":"Kanojo wa yoku ryouri o tsukurimasu."},{"jp":"昔の友達とよく遊んでいました。","en":"I used to play a lot with my old friends.","romaji":"Mukashi no tomodachi to yoku asonde imashita."},{"jp":"よくできました！","en":"Well done!","romaji":"Yoku dekimashita!"}],"example":"彼はよく勉強します。","exampleMeaning":"He studies often."},{"pattern":"～（場所）に～があります (〜basho ni 〜 ga arimasu)","meaning":"Express the existence or presence of something in a place.","formation":"Place + に + Object/Thing + が + あります","examples":[{"jp":"図書館にたくさんの本があります。","en":"There are many books in the library.","romaji":"Toshokan ni takusan no hon ga arimasu."},{"jp":"公園に池があります。","en":"There is a pond in the park.","romaji":"Kouen ni ike ga arimasu."},{"jp":"駅の前にコンビニがあります。","en":"There is a convenience store in front of the station.","romaji":"Eki no mae ni konbini ga arimasu."},{"jp":"山の上に神社があります。","en":"There is a shrine on top of the mountain.","romaji":"Yama no ue ni jinja ga arimasu."}],"example":"図書館にたくさんの本があります。","exampleMeaning":"There are many books in the library."}]
